PathwayData.put("data/reading_writing/units/L04U5.json",{"strand":"reading_writing","level":4,"cefr":"A2b","unit":5,"theme":"Desert Life","essential_question":"How do people, plants and animals live in the desert?","schema_version":"1.0","core_words":["sand","dune","cactus","Bedouin","tent","falcon","lizard","scorpion","heat","shade","dry","sandstorm","adapt","temperature"],"recycled_words":["camel","water","hot","cold","night","animal","plant","because","so","heading","letter","conserve","oasis"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L04-U5-LS1","title":"Word Power: Desert Life","lesson_type":"vocabulary","objectives":["read, say and use 14 words about desert life and 3 Tier 2 words (survive, environment, protect)","use guide words and alphabetical order to find a word quickly in a dictionary","read a dictionary entry: syllables, pronunciation, part of speech, meanings and example"],"objectives_ar":["قراءة ونطق واستخدام 14 كلمة عن الحياة في الصحراء و3 كلمات أكاديمية.","استخدام الكلمات الدليلية والترتيب الأبجدي لإيجاد الكلمة بسرعة في المعجم.","قراءة مدخل المعجم: المقاطع والنطق ونوع الكلمة والمعاني والمثال."],"success_criteria":["I can read and use the desert words in sentences.","I can say if a word is on a dictionary page by looking at the guide words.","I can find the part of speech and the right meaning in an entry."],"success_criteria_ar":["أستطيع قراءة كلمات الصحراء واستخدامها في جمل.","أستطيع معرفة هل الكلمة في صفحة المعجم بالنظر إلى الكلمات الدليلية.","أستطيع إيجاد نوع الكلمة والمعنى المناسب في المدخل."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"sand","pos":"noun","ipa":"/sænd/","definition":"tiny pieces of rock that cover deserts and beaches","arabic":"رمل","example":"The sand was hot under my feet.","image_id":"IMG-RW-L04-U5-LS1-V01","audio_id":"AUD-RW-L04-U5-LS1-V01","tier":"core"},{"word":"dune","pos":"noun","ipa":"/dun/","definition":"a hill of sand made by the wind","arabic":"كثيب رملي","example":"We climbed a tall dune.","image_id":"IMG-RW-L04-U5-LS1-V02","audio_id":"AUD-RW-L04-U5-LS1-V02","tier":"core"},{"word":"cactus","pos":"noun","ipa":"/ˈkæktəs/","definition":"a desert plant with a thick stem that stores water (plural: cacti)","arabic":"صبار","example":"A cactus can live with very little water.","image_id":"IMG-RW-L04-U5-LS1-V03","audio_id":"AUD-RW-L04-U5-LS1-V03","tier":"core"},{"word":"Bedouin","pos":"noun / adjective","ipa":"/ˈbɛduɪn/","definition":"Arab people who traditionally move from place to place in the desert","arabic":"بدو / بدوي","example":"Bedouin families lived in tents.","image_id":"IMG-RW-L04-U5-LS1-V04","audio_id":"AUD-RW-L04-U5-LS1-V04","tier":"core"},{"word":"tent","pos":"noun","ipa":"/tɛnt/","definition":"a shelter made of cloth that you can move","arabic":"خيمة","example":"We slept in a tent at the desert camp.","image_id":"IMG-RW-L04-U5-LS1-V05","audio_id":"AUD-RW-L04-U5-LS1-V05","tier":"core"},{"word":"falcon","pos":"noun","ipa":"/ˈfælkən/","definition":"a fast bird that hunts other animals","arabic":"صقر","example":"The falcon flew high above the dunes.","image_id":"IMG-RW-L04-U5-LS1-V06","audio_id":"AUD-RW-L04-U5-LS1-V06","tier":"core"},{"word":"lizard","pos":"noun","ipa":"/ˈlɪzərd/","definition":"a small animal with four short legs, a long tail and dry skin","arabic":"سحلية","example":"A lizard ran under a rock.","image_id":"IMG-RW-L04-U5-LS1-V07","audio_id":"AUD-RW-L04-U5-LS1-V07","tier":"core"},{"word":"scorpion","pos":"noun","ipa":"/ˈskɔrpiən/","definition":"a small animal with eight legs and a tail that can sting","arabic":"عقرب","example":"Scorpions hide under rocks during the day.","image_id":"IMG-RW-L04-U5-LS1-V08","audio_id":"AUD-RW-L04-U5-LS1-V08","tier":"core"},{"word":"heat","pos":"noun","ipa":"/hit/","definition":"the quality of being hot","arabic":"حرارة","example":"The heat of the sun was strong at noon.","image_id":"IMG-RW-L04-U5-LS1-V09","audio_id":"AUD-RW-L04-U5-LS1-V09","tier":"core"},{"word":"shade","pos":"noun","ipa":"/ʃeɪd/","definition":"a cool, dark place out of the sun","arabic":"ظل","example":"The camels rested in the shade of a tree.","image_id":"IMG-RW-L04-U5-LS1-V10","audio_id":"AUD-RW-L04-U5-LS1-V10","tier":"core"},{"word":"dry","pos":"adjective","ipa":"/draɪ/","definition":"with no water or very little water","arabic":"جاف","example":"The desert is very dry.","image_id":"IMG-RW-L04-U5-LS1-V11","audio_id":"AUD-RW-L04-U5-LS1-V11","tier":"core"},{"word":"sandstorm","pos":"noun","ipa":"/ˈsændstɔrm/","definition":"a strong wind that carries clouds of sand","arabic":"عاصفة رملية","example":"We stayed inside during the sandstorm.","image_id":"IMG-RW-L04-U5-LS1-V12","audio_id":"AUD-RW-L04-U5-LS1-V12","tier":"core"},{"word":"adapt","pos":"verb","ipa":"/əˈdæpt/","definition":"to change to live well in a new place or situation","arabic":"يتكيّف","example":"Desert animals adapt to the heat.","image_id":"IMG-RW-L04-U5-LS1-V13","audio_id":"AUD-RW-L04-U5-LS1-V13","tier":"core"},{"word":"temperature","pos":"noun","ipa":"/ˈtɛmprətʃər/","definition":"how hot or cold something is","arabic":"درجة الحرارة","example":"The temperature reached 45 °C.","image_id":"IMG-RW-L04-U5-LS1-V14","audio_id":"AUD-RW-L04-U5-LS1-V14","tier":"core"},{"word":"survive","pos":"verb","ipa":"/sərˈvaɪv/","definition":"to stay alive in a difficult place or situation","arabic":"يبقى على قيد الحياة / ينجو","example":"Camels can survive for days without water.","image_id":"IMG-RW-L04-U5-LS1-V15","audio_id":"AUD-RW-L04-U5-LS1-V15","tier":"tier2"},{"word":"environment","pos":"noun","ipa":"/ɪnˈvaɪrənmənt/","definition":"the air, land, water, plants and animals around us","arabic":"البيئة","example":"The desert is a hot, dry environment.","image_id":"IMG-RW-L04-U5-LS1-V16","audio_id":"AUD-RW-L04-U5-LS1-V16","tier":"tier2"},{"word":"protect","pos":"verb","ipa":"/prəˈtɛkt/","definition":"to keep safe from harm","arabic":"يحمي","example":"Thick fur protects the sand cat's feet.","image_id":"IMG-RW-L04-U5-LS1-V17","audio_id":"AUD-RW-L04-U5-LS1-V17","tier":"tier2"}],"explanation":{"text":"Words in a dictionary are in **alphabetical (ABC) order**. If two words start with the same letter, look at the **second letter**, then the **third**: *sand, scorpion, shade* (sa- → sc- → sh-).\n\nAt the top of each page are two **guide words**: the **first** word and the **last** word on that page. A word is on the page if it comes **between** the guide words in ABC order. Example: guide words **lamp – lizard** → *lion* ✔ (li-o comes before li-z), *lunch* ✘ (it comes after *lizard*).\n\nAn **entry** gives: the **headword** split into **syllables** (cac·tus), the **pronunciation** /ˈkæktəs/, the **part of speech** (noun), one or more **meanings** (numbered) and an **example sentence**. Choose the meaning that fits **your sentence**.","examples":["ABC order to the second letter: **dry, dune** (r before u).","ABC order to the third letter: **sand, sandstorm** (a shorter word comes first when the start is the same).","Guide words **heat – hill**: *hide* ✔, *help* ✔, *hot* ✘ (o comes after i).","Guide words **tail – tent**: *temperature* ✔ (tem- before ten-), *tiger* ✘.","Entry: **dune** /dun/ *noun* a hill of sand made by the wind. *The camel walked over the dune.*","Entry with two meanings: **shade** *noun* 1. a cool place out of the sun. 2. a type of a color (a light shade of blue).","*We sat in the shade of a palm tree.* → meaning 1.","Syllables help you say and spell: **tem·per·a·ture**, **en·vi·ron·ment**, **scor·pi·on**.","Part of speech helps you use the word: **adapt** (verb) → *Animals adapt.* / **dry** (adjective) → *a dry place*."],"common_errors":["✗ Looking only at the first letter. → ✓ Check the second and third letters too. (sand → scorpion → shade.)","✗ Thinking the word must be one of the guide words. → ✓ It can be anywhere between them. (Guide words = first and last.)","✗ Choosing the first meaning every time. → ✓ Choose the meaning that fits the sentence. (Read all the meanings.)","✗ a scorpion are dangerous → ✓ A scorpion is dangerous. (One scorpion → **is**.)","✗ The desert is very heat. → ✓ The desert is very hot. / The heat is strong. (**heat** is a noun; **hot** is an adjective.)","✗ Animals adapt the heat. → ✓ Animals adapt to the heat. (**adapt to** something.)","✗ two cactus → ✓ two cacti (or cactuses) (Plural: **cacti**.)"],"arabic":"الكلمات في المعجم مرتبة أبجديًا؛ إذا تشابه الحرف الأول فانظر إلى الحرف الثاني ثم الثالث.\n\nفي أعلى كل صفحة كلمتان دليليتان: أول كلمة وآخر كلمة في الصفحة، وتكون الكلمة في الصفحة إذا وقعت بينهما أبجديًا.\n\nالمدخل يعطي: الكلمة مقسّمة إلى مقاطع، والنطق، ونوع الكلمة، والمعاني مرقّمة، وجملة مثال. اختر المعنى المناسب لجملتك.\n\nانتبه: heat اسم (حرارة) وhot صفة (حار)، ونقول adapt to."},"video":{"script":[{"time":"00:00–00:20","narration":"Welcome to the desert! Saqr the falcon will show us around.","on_screen":"Desert Life 🐪","visual":"Saqr flies over golden dunes at sunrise."},{"time":"00:20–01:10","narration":"Sand, dunes and a sandstorm! Heat, shade and dry ground. A lizard, a scorpion and a cactus!","on_screen":"sand · dune · sandstorm · heat · shade · dry · lizard · scorpion · cactus","visual":"Quick clips of each desert word."},{"time":"01:10–01:40","narration":"Bedouin families live in tents. Living things adapt to survive the high temperature.","on_screen":"Bedouin · tent · adapt · survive · temperature · environment · protect","visual":"A goat-hair tent; a thermometer rising."},{"time":"01:40–02:30","narration":"Lost in the dictionary? Use the guide words at the top of the page!","on_screen":"Guide words: heat – hill","visual":"A dictionary page with two guide words; 'hide' slides in between them."},{"time":"02:30–03:00","narration":"An entry tells you syllables, pronunciation, part of speech and meaning.","on_screen":"dune /dun/ noun","visual":"A dictionary entry is labelled part by part."}],"captions_ar":["مرحبًا بكم في الصحراء! سيأخذنا الصقر في جولة.","رمل وكثبان وعاصفة رملية! حرارة وظل وأرض جافة. سحلية وعقرب وصبار!","تعيش العائلات البدوية في الخيام، وتتكيّف الكائنات الحية لتبقى في درجات الحرارة العالية.","تائه في المعجم؟ استخدم الكلمات الدليلية في أعلى الصفحة!","المدخل يخبرك بالمقاطع والنطق ونوع الكلمة والمعنى."],"voice":"Narrator: American English, adventurous male explorer voice, speed 0.90. Saqr the falcon guides the tour."},"texts":[],"activities":[{"id":"RW-L04-U5-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"A hill of sand made by the wind is a ___.","answer":"dune","explanation":"Dune.","explanation_ar":"كثيب.","options":["tent","dune","shade","cactus"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"We sat in the ___ of a tree to get out of the sun.","answer":"shade","explanation":"Shade.","explanation_ar":"الظل.","options":["heat","shade","sandstorm","temperature"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A small animal with eight legs and a stinging tail is a ___.","answer":"scorpion","explanation":"Scorpion.","explanation_ar":"عقرب.","options":["scorpion","lizard","falcon","camel"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A strong wind filled the air with sand. It was a ___.","answer":"sandstorm","explanation":"Sandstorm.","explanation_ar":"عاصفة رملية.","options":["dune","tent","sandstorm","Bedouin"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The thermometer showed 45 °C. The ___ was very high.","answer":"temperature","explanation":"Temperature.","explanation_ar":"درجة الحرارة.","options":["shade","environment","tent","temperature"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A fast hunting bird that people train in Saudi Arabia is a ___.","answer":"falcon","explanation":"Falcon.","explanation_ar":"صقر.","options":["falcon","lizard","scorpion","jerboa"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L04-U5-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Dictionary skills. Choose.","instructions_ar":"مهارات المعجم: اختر.","items":[{"q":"Which group of desert words is in ABC order?","answer":"dry, dune, falcon","explanation":"dr- before du-.","explanation_ar":"الترتيب الصحيح.","options":["dune, dry, falcon","dry, dune, falcon","falcon, dry, dune","dry, falcon, dune"],"dok":1,"skill":"ABC order","stage":"guided"},{"q":"The guide words on a page are *heat – hill*. Which word is on the page?","answer":"hide","explanation":"hea < hid < hil.","explanation_ar":"hide.","options":["hot","hat","horse","hide"],"dok":2,"skill":"guide words","stage":"guided"},{"q":"The guide words are *tail – tent*. Which word is NOT on the page?","answer":"tiger","explanation":"ti- comes after te-.","explanation_ar":"tiger.","options":["tiger","temperature","tea","taxi"],"dok":2,"skill":"guide words","stage":"guided"},{"q":"Look at the entry: *cac·tus /ˈkæktəs/ noun*. How many syllables does *cactus* have?","answer":"two","explanation":"cac·tus.","explanation_ar":"مقطعان.","options":["one","three","two","four"],"dok":1,"skill":"entries","stage":"guided"},{"q":"Entry: *shade (noun) 1. a cool place out of the sun 2. a type of a color*. Which meaning fits *The camels rested in the shade*?","answer":"meaning 1","explanation":"Context.","explanation_ar":"المعنى الأول.","options":["meaning 2","both meanings","meaning 1","neither meaning"],"dok":2,"skill":"multiple meanings","stage":"guided"},{"q":"Which word comes FIRST in a dictionary?","answer":"sand","explanation":"Shorter word first; sa- before sc-.","explanation_ar":"sand.","options":["sandstorm","scorpion","shade","sand"],"dok":3,"skill":"ABC order","stage":"guided"}]},{"id":"RW-L04-U5-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"Camels can ________ for many days without drinking water.","answer":"survive","explanation":"Stay alive.","explanation_ar":"تبقى على قيد الحياة.","stage":"freer"},{"q":"The desert is a hot, dry ________.","answer":"environment","explanation":"Everything around.","explanation_ar":"بيئة.","stage":"freer"},{"q":"A hat and loose clothes ________ you from the strong sun.","answer":"protect","explanation":"Keep safe.","explanation_ar":"تحمي.","stage":"freer"},{"q":"Bedouin families lived in ________ made of goat hair.","answer":"tents","explanation":"Shelters.","explanation_ar":"خيام.","stage":"freer"},{"q":"Desert plants and animals ________ to the heat in clever ways.","answer":"adapt","explanation":"Change to live well.","explanation_ar":"تتكيّف.","stage":"freer"},{"q":"The ground was so ________ that it had cracks in it.","answer":"dry","explanation":"No water.","explanation_ar":"جافة.","stage":"freer"}]},{"id":"RW-L04-U5-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write with the new words and the dictionary.","instructions_ar":"اكتب باستخدام الكلمات الجديدة والمعجم.","items":[{"q":"Put these words in ABC order: *scorpion, sand, shade, survive*.","answer":"sand, scorpion, shade, survive","explanation":"ABC order.","explanation_ar":"ترتيب أبجدي.","dok":2,"skill":"ABC order","stage":"production"},{"q":"Write a dictionary entry for *lizard*: syllables, part of speech, meaning and an example.","answer":"liz·ard (noun) a small animal with four short legs, a long tail and dry skin. A lizard ran under a rock.","explanation":"Entry.","explanation_ar":"مدخل.","dok":2,"skill":"entries","stage":"production"},{"q":"How do people protect themselves from the desert heat? Use two unit words.","answer":"They stay in the shade at noon and wear loose clothes to protect their skin from the heat.","explanation":"Two words.","explanation_ar":"كلمتان.","dok":2,"skill":"connect","stage":"production"},{"q":"Why is it useful to know guide words?","answer":"Because you can find a word quickly without reading every page.","explanation":"Reason.","explanation_ar":"سبب.","dok":3,"skill":"reasoning","stage":"production"}]}],"game":{"name":"Dune Dictionary Dash","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Dune dash: guide words appear on two sand dunes; desert words roll down between them. The child taps 'on the page' or 'not on the page' before the word reaches the bottom; correct answers help a camel cross the desert.","Each team gets five page cards with guide words.","The teacher shows a desert word.","Teams race to hold up the page card where the word belongs.","The first correct team reads the word's meaning from the entry.","Each correct page = 1 point; a correct meaning = 1 bonus point."],"data":[]},"exit_quiz":[{"q":"What are *guide words*?","answer":"the first and last words on a dictionary page","explanation":"Guide words.","explanation_ar":"أول وآخر كلمة في الصفحة.","options":["the hardest words","the words in the title","words in another language","the first and last words on a dictionary page"],"dok":1,"skill":"guide words"},{"q":"Which word means *to stay alive in a difficult place*?","answer":"survive","explanation":"Survive.","explanation_ar":"يبقى على قيد الحياة.","options":["survive","protect","adapt","dry"],"dok":1,"skill":"vocabulary"},{"q":"Which word comes FIRST in ABC order?","answer":"lizard","explanation":"f comes before l, s and t.","explanation_ar":"falcon.","options":["scorpion","tent","lizard","falcon"],"dok":1,"skill":"ABC order"},{"q":"*The Bedouin tent **protected** the family from the sun.* *Protected* means ___.","answer":"kept safe","explanation":"Protect.","explanation_ar":"حمت.","options":["kept safe","made hot","carried away","hid away from"],"dok":1,"skill":"vocabulary in context"},{"q":"Which sentence about the desert is correct?","answer":"The heat in the desert is very strong.","explanation":"heat = noun.","explanation_ar":"صحيحة.","options":["The desert is very heat.","The heat in the desert are very strong.","The heat in the desert is very strong.","The desert very hot is."],"dok":2,"skill":"grammar"},{"q":"The guide words are *dry – dust*. Which word is on the page?","answer":"dune","explanation":"dr- … du-.","explanation_ar":"dune.","options":["drum","door","date","dune"],"dok":2,"skill":"guide words"},{"q":"In a dictionary entry, what does *(noun)* tell you?","answer":"the part of speech","explanation":"Part of speech.","explanation_ar":"نوع الكلمة.","options":["the number of syllables","the part of speech","the meaning","the page number"],"dok":2,"skill":"entries"},{"q":"Which sentence uses *adapt* correctly?","answer":"Desert animals adapt to the heat.","explanation":"adapt to.","explanation_ar":"صحيحة.","options":["Desert animals adapt the heat.","Desert animals adapt to the heat.","Desert animals adapting heat.","Desert animals adapts to the heat."],"dok":2,"skill":"grammar"},{"q":"Entry: *dry (adjective) 1. with no water 2. not funny or not exciting*. Which meaning fits *The teacher told a dry joke*?","answer":"meaning 2","explanation":"Context.","explanation_ar":"المعنى الثاني.","options":["meaning 1","both meanings","neither meaning","meaning 2"],"dok":3,"skill":"multiple meanings"},{"q":"Why does a dictionary split words into syllables?","answer":"to help you say and spell long words","explanation":"Syllables.","explanation_ar":"لتساعدك على النطق والتهجئة.","options":["to make the words shorter","to show the meaning","to help you say and spell long words","to show where the word comes from"],"dok":3,"skill":"entries"}],"images":[{"id":"IMG-RW-L04-U5-LS1-V01","prompt":"Picture for the word 'sand': golden sand close up"},{"id":"IMG-RW-L04-U5-LS1-V02","prompt":"Picture for the word 'dune': large sand dunes"},{"id":"IMG-RW-L04-U5-LS1-V03","prompt":"Picture for the word 'cactus': a green cactus with spines"},{"id":"IMG-RW-L04-U5-LS1-V04","prompt":"Picture for the word 'Bedouin': a Bedouin tent with camels nearby"},{"id":"IMG-RW-L04-U5-LS1-V05","prompt":"Picture for the word 'tent': a black goat-hair tent"},{"id":"IMG-RW-L04-U5-LS1-V06","prompt":"Picture for the word 'falcon': a falcon on a gloved hand"},{"id":"IMG-RW-L04-U5-LS1-V07","prompt":"Picture for the word 'lizard': a spiny-tailed lizard on sand"},{"id":"IMG-RW-L04-U5-LS1-V08","prompt":"Picture for the word 'scorpion': a scorpion on sand"},{"id":"IMG-RW-L04-U5-LS1-V09","prompt":"Picture for the word 'heat': a sun over hot sand with heat waves"},{"id":"IMG-RW-L04-U5-LS1-V10","prompt":"Picture for the word 'shade': camels in the shade of an acacia tree"},{"id":"IMG-RW-L04-U5-LS1-V11","prompt":"Picture for the word 'dry': cracked dry ground"},{"id":"IMG-RW-L04-U5-LS1-V12","prompt":"Picture for the word 'sandstorm': a wall of sand moving across the desert"},{"id":"IMG-RW-L04-U5-LS1-V13","prompt":"Picture for the word 'adapt': a sand cat with furry feet"},{"id":"IMG-RW-L04-U5-LS1-V14","prompt":"Picture for the word 'temperature': a thermometer showing 45 °C"},{"id":"IMG-RW-L04-U5-LS1-V15","prompt":"Picture for the word 'survive': a camel walking across the desert"},{"id":"IMG-RW-L04-U5-LS1-V16","prompt":"Picture for the word 'environment': a desert scene with plants, animals and sky"},{"id":"IMG-RW-L04-U5-LS1-V17","prompt":"Picture for the word 'protect': a hat and scarf protecting a child from the sun"},{"id":"IMG-RW-L04-U5-LS1-01","prompt":"A desert scene with dunes, a tent, camels and desert animals."},{"id":"IMG-RW-L04-U5-LS1-02","prompt":"Pictures of desert words."},{"id":"IMG-RW-L04-U5-LS1-03","prompt":"A labelled dictionary page."}],"audio":[{"id":"AUD-RW-L04-U5-LS1-V01","script":"sand. The sand was hot under my feet."},{"id":"AUD-RW-L04-U5-LS1-V02","script":"dune. We climbed a tall dune."},{"id":"AUD-RW-L04-U5-LS1-V03","script":"cactus. A cactus can live with very little water."},{"id":"AUD-RW-L04-U5-LS1-V04","script":"Bedouin. Bedouin families lived in tents."},{"id":"AUD-RW-L04-U5-LS1-V05","script":"tent. We slept in a tent at the desert camp."},{"id":"AUD-RW-L04-U5-LS1-V06","script":"falcon. The falcon flew high above the dunes."},{"id":"AUD-RW-L04-U5-LS1-V07","script":"lizard. A lizard ran under a rock."},{"id":"AUD-RW-L04-U5-LS1-V08","script":"scorpion. Scorpions hide under rocks during the day."},{"id":"AUD-RW-L04-U5-LS1-V09","script":"heat. The heat of the sun was strong at noon."},{"id":"AUD-RW-L04-U5-LS1-V10","script":"shade. The camels rested in the shade of a tree."},{"id":"AUD-RW-L04-U5-LS1-V11","script":"dry. The desert is very dry."},{"id":"AUD-RW-L04-U5-LS1-V12","script":"sandstorm. We stayed inside during the sandstorm."},{"id":"AUD-RW-L04-U5-LS1-V13","script":"adapt. Desert animals adapt to the heat."},{"id":"AUD-RW-L04-U5-LS1-V14","script":"temperature. The temperature reached 45 °C."},{"id":"AUD-RW-L04-U5-LS1-V15","script":"survive. Camels can survive for days without water."},{"id":"AUD-RW-L04-U5-LS1-V16","script":"environment. The desert is a hot, dry environment."},{"id":"AUD-RW-L04-U5-LS1-V17","script":"protect. Thick fur protects the sand cat's feet."},{"id":"AUD-RW-L04-U5-LS1-VID","script":"Welcome to the desert! Saqr the falcon will show us around. Sand, dunes and a sandstorm! Heat, shade and dry ground. A lizard, a scorpion and a cactus! Bedouin families live in tents. Living things adapt to survive the high temperature. Lost in the dictionary? Use the guide words at the top of the page! An entry tells you syllables, pronunciation, part of speech and meaning."}]},{"id":"RW-L04-U5-LS2","title":"Life in the Sand Sea","lesson_type":"close_reading","objectives":["read an informational article of about 310 words about life in the Empty Quarter","explain how a feature helps a living thing survive (feature → job)","answer literal, inferential and evaluative questions with evidence from the text"],"objectives_ar":["قراءة مقال معلوماتي من نحو 330 كلمة عن الحياة في الربع الخالي.","شرح كيف تساعد صفةٌ الكائنَ الحي على البقاء (الصفة ← وظيفتها).","الإجابة عن أسئلة حرفية واستنتاجية وتقييمية مع الدليل من النص."],"success_criteria":["I can find a feature of a plant, an animal or a person's home in the text.","I can explain the job of the feature: how it helps them survive.","I can correct a common mistake (camels store water in their humps) with evidence."],"success_criteria_ar":["أستطيع إيجاد صفة لنبات أو حيوان أو مسكن في النص.","أستطيع شرح وظيفة الصفة: كيف تساعد على البقاء.","أستطيع تصحيح خطأ شائع (الجمال تخزن الماء في سنامها) بالدليل."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"peninsula","pos":"noun","ipa":"/pəˈnɪnsələ/","definition":"land with water on three sides","arabic":"شبه جزيرة","example":"Saudi Arabia is on the Arabian Peninsula.","image_id":"IMG-RW-L04-U5-LS2-V01","audio_id":"AUD-RW-L04-U5-LS2-V01","tier":"core"},{"word":"quarter","pos":"noun","ipa":"/ˈkwɔrtər/","definition":"one of four equal parts; an area","arabic":"ربع","example":"The Empty Quarter is a huge desert.","image_id":"IMG-RW-L04-U5-LS2-V02","audio_id":"AUD-RW-L04-U5-LS2-V02","tier":"core"},{"word":"root","pos":"noun","ipa":"/rut/","definition":"the part of a plant under the ground","arabic":"جذر","example":"Some roots grow very deep.","image_id":"IMG-RW-L04-U5-LS2-V03","audio_id":"AUD-RW-L04-U5-LS2-V03","tier":"core"},{"word":"burrow","pos":"noun","ipa":"/ˈbɝoʊ/","definition":"a hole in the ground where an animal lives","arabic":"جُحر","example":"The lizard hides in its burrow.","image_id":"IMG-RW-L04-U5-LS2-V04","audio_id":"AUD-RW-L04-U5-LS2-V04","tier":"core"},{"word":"furry","pos":"adjective","ipa":"/ˈfɝi/","definition":"covered with soft, thick hair","arabic":"مكسو بالفرو","example":"The sand cat has furry feet.","image_id":"IMG-RW-L04-U5-LS2-V05","audio_id":"AUD-RW-L04-U5-LS2-V05","tier":"core"},{"word":"hump","pos":"noun","ipa":"/hʌmp/","definition":"a large round shape on a camel's back","arabic":"سنام","example":"A camel's hump stores fat.","image_id":"IMG-RW-L04-U5-LS2-V06","audio_id":"AUD-RW-L04-U5-LS2-V06","tier":"core"},{"word":"weave","pos":"verb","ipa":"/wiv/","definition":"to make cloth by crossing threads over and under (past: wove; woven)","arabic":"ينسج","example":"Bedouin women wove tents from goat hair.","image_id":"IMG-RW-L04-U5-LS2-V07","audio_id":"AUD-RW-L04-U5-LS2-V07","tier":"core"}],"explanation":{"text":"Informational texts often explain **how** and **why**. In this article, each living thing has a **feature** (something it has or does) with a **job** (how it helps it survive).\n\nUse a **Feature → Job** sentence: ***[Living thing] has / does [feature], so / which / that [job].*** Look for signal words: **so, which, that, to, because**.\n\nCheck facts carefully. Some ideas that many people believe are **not true**. Always go back to the **text** for evidence: *Their humps store fat, not water.*","examples":["**Plants – long roots** → reach water deep under the ground.","**Plants – small, thin leaves** → lose less water in the hot sun (*so they lose less water*).","**Seeds – wait for years** → grow quickly after a rare rain.","**Scorpion – hides under rocks** → stays out of the heat.","**Sand cat – furry feet** → protect it from the hot sand (*that protect it*).","**Spiny-tailed lizard – warms itself in the morning sun, hides when it is too hot** → keeps its body at a good temperature.","**Camel – hump of fat** → gives energy on long walks (*not* water!).","**Bedouin tent – woven goat hair** → shade from the sun and helps keep out the rain.","Full sentence: ***The sand cat has furry feet, which protect it from the hot sand.***"],"common_errors":["✗ Camels store water in their humps. → ✓ Camels' humps store fat, not water. (Check the text!)","✗ The cat feet are furry for beauty. → ✓ The sand cat's feet are furry to protect it from the hot sand. (Give the **job**, not a guess.)","✗ Plants has long roots. → ✓ Plants have long roots. (Plural → **have**.)","✗ Many animal come out at night. → ✓ Many animals come out at night. (Plural **-s**.)","✗ The lizard hide in its burrow. → ✓ The lizard hides in its burrow. (One lizard → **hides**.)","✗ Giving the feature with no job. → ✓ Add so / which / to + the job. (Feature → job.)"],"arabic":"تشرح النصوص المعلوماتية كيف ولماذا؛ ولكل كائن في المقال صفة (شيء يملكه أو يفعله) ووظيفة (كيف تساعده على البقاء).\n\nاستخدم جملة الصفة ← الوظيفة مع كلمات مثل so وwhich وthat وto وbecause.\n\nتحقّق من الحقائق: بعض ما يعتقده الناس غير صحيح؛ فسنام الجمل يخزن الدهون لا الماء.\n\nمثال: للقط الرملي أقدام مكسوة بالفرو تحميه من الرمل الحار."},"video":{"script":[{"time":"00:00–00:20","narration":"Is the Empty Quarter really empty? Let's fly over the sand sea with Saqr!","on_screen":"Life in the Sand Sea","visual":"Aerial view of giant dunes rolling like waves."},{"time":"00:20–01:50","narration":"In the south of the Arabian Peninsula lies the Rub' al Khali…","on_screen":"(article, section by section)","visual":"A thermometer at 50 °C; long roots under a desert plant; seeds blooming after rain; a sand cat's furry paws; a lizard in the morning sun; a camel; a goat-hair tent."},{"time":"01:50–02:25","narration":"Feature → job! Furry feet protect the sand cat from hot sand.","on_screen":"Feature → Job","visual":"Arrows link each feature to its job."},{"time":"02:25–02:45","narration":"True or false? Camels store water in their humps… FALSE! Humps store fat.","on_screen":"Myth buster ❌","visual":"A camel's hump with a label: fat = energy."},{"time":"02:45–03:00","narration":"Plants, animals and people – all found clever ways to survive!","on_screen":"Survive 🌵🐪⛺","visual":"Saqr lands on a tent pole at sunset."}],"captions_ar":["هل الربع الخالي خالٍ حقًا؟ لنحلّق فوق بحر الرمال مع الصقر!","في جنوب شبه الجزيرة العربية يقع الربع الخالي…","الصفة ← الوظيفة! الأقدام المكسوة بالفرو تحمي القط الرملي من الرمل الحار.","صحيح أم خطأ؟ الجمال تخزن الماء في سنامها… خطأ! السنام يخزن الدهون.","النباتات والحيوانات والناس وجدوا طرقًا ذكية للبقاء!"],"voice":"Narrator: American English, nature-documentary female voice, speed 0.90. Saqr the falcon adds short comments."},"texts":[{"type":"reading","title":"Life in the Sand Sea","body":"In the south of the Arabian Peninsula lies the Rub' al Khali, or the Empty Quarter. It is one of the largest sand deserts in the world. Its giant dunes roll like waves, so people call it a \"sand sea.\" But is this sea really empty? Not at all!\n\n**Hot Days, Cold Nights**\n\nIn summer, the afternoon temperature can reach 50 °C. At night, however, the sand loses its heat quickly, and winter nights can be very cold. Rain is rare, and strong winds sometimes lift the sand into a sandstorm.\n\n**Plants That Save Water**\n\nDesert plants adapt to this dry environment. Some have very long roots that reach water deep under the ground. Others have small, thin leaves, so they lose less water in the hot sun. After a rare rain, seeds that have waited for years can grow and flower in just a few days.\n\n**Animals That Hide from the Heat**\n\nMany desert animals rest in burrows or in the shade during the day and come out at night, when it is cool. The scorpion hides under rocks, and the sand cat walks on furry feet that protect it from the hot sand. The spiny-tailed lizard warms itself in the morning sun and hides in its burrow when the day gets too hot. Camels can walk for days without drinking. Their humps store fat, not water, and the fat gives them energy.\n\n**People of the Desert**\n\nFor hundreds of years, Bedouin families have lived in the desert with their camels and goats. They moved from place to place to find water and grass for their animals. Their tents were woven from goat hair, which gives shade from the sun and helps keep out the rain.\n\nThe desert is a hard place to live, but its plants, animals and people have found clever ways to survive.","word_count":307,"audio_id":"AUD-RW-L04-U5-LS2-T1","id":"TXT-RW-L04-U5-LS2-1","genre":"informational","role":"main","difficulty":"450L–600L","glossary":[{"word":"peninsula","definition":"land with water on three sides","arabic":"شبه جزيرة"},{"word":"burrow","definition":"a hole in the ground where an animal lives","arabic":"جُحر"},{"word":"woven","definition":"made by crossing threads over and under each other","arabic":"منسوج"}]}],"activities":[{"id":"RW-L04-U5-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the article. Choose the answer.","instructions_ar":"اقرأ المقال واختر الإجابة.","items":[{"q":"Why do people call the Empty Quarter a *sand sea*?","answer":"Its giant dunes roll like waves.","explanation":"Introduction.","explanation_ar":"لأن كثبانه تتموج كالأمواج.","options":["It is full of water.","Its giant dunes roll like waves.","It is next to the sea.","Fish live in the sand."],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How hot can a summer afternoon be in the Empty Quarter?","answer":"50 °C","explanation":"Hot Days, Cold Nights.","explanation_ar":"50 درجة.","options":["15 °C","50 °C","100 °C","0 °C"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Why can winter nights be very cold?","answer":"The sand loses its heat quickly.","explanation":"Hot Days, Cold Nights.","explanation_ar":"لأن الرمل يفقد حرارته بسرعة.","options":["It rains every night.","The sun shines at night.","Sandstorms are warm.","The sand loses its heat quickly."],"dok":2,"skill":"cause and effect","stage":"controlled"},{"q":"What happens after a rare rain?","answer":"Seeds can grow and flower in a few days.","explanation":"Plants That Save Water.","explanation_ar":"تنمو البذور وتزهر.","options":["Seeds can grow and flower in a few days.","The dunes disappear.","Camels stop walking.","Scorpions build tents."],"dok":1,"skill":"key details","stage":"controlled"},{"q":"When do many desert animals come out?","answer":"at night, when it is cool","explanation":"Animals That Hide from the Heat.","explanation_ar":"ليلًا.","options":["at noon, when it is hottest","only in sandstorms","at night, when it is cool","never"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What were Bedouin tents made from?","answer":"goat hair","explanation":"People of the Desert.","explanation_ar":"شعر الماعز.","options":["goat hair","plastic","palm leaves","camel bones"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L04-U5-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Features and their jobs. Choose.","instructions_ar":"الصفات ووظائفها: اختر.","items":[{"q":"What is the job of the very long roots of some desert plants?","answer":"to reach water deep under the ground","explanation":"Feature → job.","explanation_ar":"الوصول إلى الماء العميق.","options":["to reach water deep under the ground","to hold up the sand","to keep animals away","to make shade"],"dok":1,"skill":"feature and job","stage":"guided"},{"q":"Why do some desert plants have small, thin leaves?","answer":"so they lose less water in the hot sun","explanation":"so → job.","explanation_ar":"لتفقد ماءً أقل.","options":["so they look pretty","so they lose less water in the hot sun","so camels can't eat them","so they grow faster in winter"],"dok":2,"skill":"feature and job","stage":"guided"},{"q":"How do the sand cat's furry feet help it?","answer":"They protect it from the hot sand.","explanation":"that protect it.","explanation_ar":"تحميه من الرمل الحار.","options":["They protect it from the hot sand.","They help it swim.","They keep it clean.","They help it climb trees."],"dok":2,"skill":"feature and job","stage":"guided"},{"q":"What do camels' humps store?","answer":"fat, which gives them energy","explanation":"Myth vs. fact.","explanation_ar":"الدهون.","options":["water for long walks","sand","food for their babies","fat, which gives them energy"],"dok":2,"skill":"correcting misconceptions","stage":"guided"},{"q":"Why did Bedouin families move from place to place?","answer":"to find water and grass for their animals","explanation":"People of the Desert.","explanation_ar":"للبحث عن الماء والمرعى.","options":["to visit cities","to escape the rain","to find water and grass for their animals","to sell tents"],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Which sentence BEST states the main idea of the whole article?","answer":"Plants, animals and people have found clever ways to survive in the desert.","explanation":"Conclusion.","explanation_ar":"الفكرة الرئيسية.","options":["The Empty Quarter is in the south.","Scorpions hide under rocks.","Camels can walk for days.","Plants, animals and people have found clever ways to survive in the desert."],"dok":3,"skill":"main idea","stage":"guided"}]},{"id":"RW-L04-U5-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence.","instructions_ar":"ابحث عن الدليل.","items":[{"q":"Underline the sentence that proves camels do NOT store water in their humps.","answer":"Their humps store fat, not water, and the fat gives them energy.","explanation":"Myth buster.","explanation_ar":"دليل التصحيح.","evidence":"Their humps store fat, not water, and the fat gives them energy.","text_id":"TXT-RW-L04-U5-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["In the south of the Arabian Peninsula lies the Rub' al Khali, or the Empty Quarter.","It is one of the largest sand deserts in the world.","Its giant dunes roll like waves, so people call it a \"sand sea.\"","But is this sea really empty?","Not at all!","**Hot Days, Cold Nights**","In summer, the afternoon temperature can reach 50 °C.","At night, however, the sand loses its heat quickly, and winter nights can be very cold.","Rain is rare, and strong winds sometimes lift the sand into a sandstorm.","**Plants That Save Water**","Desert plants adapt to this dry environment.","Some have very long roots that reach water deep under the ground.","Others have small, thin leaves, so they lose less water in the hot sun.","After a rare rain, seeds that have waited for years can grow and flower in just a few days.","**Animals That Hide from the Heat**","Many desert animals rest in burrows or in the shade during the day and come out at night, when it is cool.","The scorpion hides under rocks, and the sand cat walks on furry feet that protect it from the hot sand.","The spiny-tailed lizard warms itself in the morning sun and hides in its burrow when the day gets too hot.","Camels can walk for days without drinking.","Their humps store fat, not water, and the fat gives them energy.","**People of the Desert**","For hundreds of years, Bedouin families have lived in the desert with their camels and goats.","They moved from place to place to find water and grass for their animals.","Their tents were woven from goat hair, which gives shade from the sun and helps keep out the rain.","The desert is a hard place to live, but its plants, animals and people have found clever ways to survive."]},{"q":"Underline how the spiny-tailed lizard deals with the heat.","answer":"The spiny-tailed lizard warms itself in the morning sun and hides in its burrow when the day gets too hot.","explanation":"Behavior.","explanation_ar":"السلوك.","evidence":"The spiny-tailed lizard warms itself in the morning sun and hides in its burrow when the day gets too hot.","text_id":"TXT-RW-L04-U5-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["In the south of the Arabian Peninsula lies the Rub' al Khali, or the Empty Quarter.","It is one of the largest sand deserts in the world.","Its giant dunes roll like waves, so people call it a \"sand sea.\"","But is this sea really empty?","Not at all!","**Hot Days, Cold Nights**","In summer, the afternoon temperature can reach 50 °C.","At night, however, the sand loses its heat quickly, and winter nights can be very cold.","Rain is rare, and strong winds sometimes lift the sand into a sandstorm.","**Plants That Save Water**","Desert plants adapt to this dry environment.","Some have very long roots that reach water deep under the ground.","Others have small, thin leaves, so they lose less water in the hot sun.","After a rare rain, seeds that have waited for years can grow and flower in just a few days.","**Animals That Hide from the Heat**","Many desert animals rest in burrows or in the shade during the day and come out at night, when it is cool.","The scorpion hides under rocks, and the sand cat walks on furry feet that protect it from the hot sand.","The spiny-tailed lizard warms itself in the morning sun and hides in its burrow when the day gets too hot.","Camels can walk for days without drinking.","Their humps store fat, not water, and the fat gives them energy.","**People of the Desert**","For hundreds of years, Bedouin families have lived in the desert with their camels and goats.","They moved from place to place to find water and grass for their animals.","Their tents were woven from goat hair, which gives shade from the sun and helps keep out the rain.","The desert is a hard place to live, but its plants, animals and people have found clever ways to survive."]},{"q":"Why does the writer ask *But is this sea really empty?*","answer":"to make readers curious about the life in the desert","explanation":"Author's craft.","explanation_ar":"لإثارة فضول القارئ.","options":["because the writer does not know","to start a story","to make readers curious about the life in the desert","to give a fact about water"],"dok":2,"skill":"author's craft","stage":"freer"},{"q":"What can you infer about the name *Empty Quarter*?","answer":"It looks empty, but many living things are there.","explanation":"Inference.","explanation_ar":"يبدو خاليًا لكنه مليء بالحياة.","options":["Nothing lives there at all.","It looks empty, but many living things are there.","It is a quarter of the world.","It is full of cities."],"dok":3,"skill":"inference","stage":"freer"}]},{"id":"RW-L04-U5-LS2-A4","type":"open","stage":"production","instructions":"Writing: Explain with Feature → Job sentences.","instructions_ar":"اشرح بجمل الصفة ← الوظيفة.","items":[{"q":"Write a Feature → Job sentence about the scorpion.","answer":"The scorpion hides under rocks during the day, so it stays out of the heat.","explanation":"Feature → job.","explanation_ar":"الصفة ← الوظيفة.","dok":2,"skill":"feature and job","stage":"production"},{"q":"Write a Feature → Job sentence about the Bedouin tent.","answer":"Bedouin tents were woven from goat hair, which gives shade and helps keep out the rain.","explanation":"Feature → job.","explanation_ar":"الصفة ← الوظيفة.","dok":2,"skill":"feature and job","stage":"production"},{"q":"A friend says, *Camels drink from their humps.* What would you tell him? Use evidence.","answer":"That isn't true. The article says, 'Their humps store fat, not water, and the fat gives them energy.'","explanation":"Correct with evidence.","explanation_ar":"صحّح بالدليل.","dok":3,"skill":"correcting misconceptions","stage":"production"},{"q":"Which desert living thing do you think is the cleverest survivor? Why?","answer":"The seeds, because they can wait for years and then grow in a few days after rain.","explanation":"Opinion + reason.","explanation_ar":"رأي + سبب.","dok":3,"skill":"evaluate","stage":"production"}]},{"id":"RW-L04-U5-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Life in the Sand Sea\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Life in the Sand Sea”.","answer":"307 words","title":"Life in the Sand Sea","body":"In the south of the Arabian Peninsula lies the Rub' al Khali, or the Empty Quarter. It is one of the largest sand deserts in the world. Its giant dunes roll like waves, so people call it a \"sand sea.\" But is this sea really empty? Not at all!\n\n**Hot Days, Cold Nights**\n\nIn summer, the afternoon temperature can reach 50 °C. At night, however, the sand loses its heat quickly, and winter nights can be very cold. Rain is rare, and strong winds sometimes lift the sand into a sandstorm.\n\n**Plants That Save Water**\n\nDesert plants adapt to this dry environment. Some have very long roots that reach water deep under the ground. Others have small, thin leaves, so they lose less water in the hot sun. After a rare rain, seeds that have waited for years can grow and flower in just a few days.\n\n**Animals That Hide from the Heat**\n\nMany desert animals rest in burrows or in the shade during the day and come out at night, when it is cool. The scorpion hides under rocks, and the sand cat walks on furry feet that protect it from the hot sand. The spiny-tailed lizard warms itself in the morning sun and hides in its burrow when the day gets too hot. Camels can walk for days without drinking. Their humps store fat, not water, and the fat gives them energy.\n\n**People of the Desert**\n\nFor hundreds of years, Bedouin families have lived in the desert with their camels and goats. They moved from place to place to find water and grass for their animals. Their tents were woven from goat hair, which gives shade from the sun and helps keep out the rain.\n\nThe desert is a hard place to live, but its plants, animals and people have found clever ways to survive.","words":307,"limit":231}],"time_limit_sec":231}],"game":{"name":"Desert Survivor Match","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Survivor board: the child drags each feature to its job; correct matches help a desert animal reach the shade before the sun gets too high. A myth card (humps store water) must be thrown in the bin.","Teams get mixed feature and job cards.","They match each feature to its job.","They say the full sentence with so, which or to.","One card is a myth – the team that finds and corrects it gets 3 bonus points.","Each correct match = 1 point."],"data":[]},"exit_quiz":[{"q":"Where is the Empty Quarter?","answer":"in the south of the Arabian Peninsula","explanation":"Introduction.","explanation_ar":"جنوب شبه الجزيرة العربية.","options":["in the south of the Arabian Peninsula","in the north of Africa","next to the North Pole","in a big city"],"dok":1,"skill":"key details"},{"q":"What is a *burrow*?","answer":"a hole in the ground where an animal lives","explanation":"Glossary.","explanation_ar":"جُحر.","options":["a kind of tent","a hole in the ground where an animal lives","a sandstorm","a desert plant"],"dok":1,"skill":"vocabulary"},{"q":"Which feature helps some desert plants reach water deep underground?","answer":"very long roots","explanation":"Plants section.","explanation_ar":"الجذور الطويلة.","options":["small flowers","bright colors","thin stems","very long roots"],"dok":1,"skill":"feature and job"},{"q":"*Bedouin women **wove** tents from goat hair.* *Wove* is the past tense of ___.","answer":"weave","explanation":"Irregular past.","explanation_ar":"weave.","options":["wave","wake","weave","wear"],"dok":2,"skill":"grammar"},{"q":"Which sentence about desert animals is correct?","answer":"Many desert animals come out at night.","explanation":"Plural + come.","explanation_ar":"صحيحة.","options":["Many desert animal comes out at night.","Many desert animals comes out at night.","Many desert animals coming out at night.","Many desert animals come out at night."],"dok":2,"skill":"grammar"},{"q":"Why do many desert animals rest during the day?","answer":"to stay out of the heat","explanation":"Cause.","explanation_ar":"لتتجنب الحرارة.","options":["because they are lazy","to stay out of the heat","because they are hungry","to watch the falcons"],"dok":2,"skill":"cause and effect"},{"q":"Which is a FALSE idea that the article corrects?","answer":"Camels store water in their humps.","explanation":"Myth.","explanation_ar":"فكرة خاطئة.","options":["Camels store water in their humps.","Scorpions hide under rocks.","Winter nights can be cold.","Some seeds wait for years."],"dok":2,"skill":"correcting misconceptions"},{"q":"Which sentence is the BEST Feature → Job sentence?","answer":"The sand cat has furry feet, which protect it from the hot sand.","explanation":"Feature + job.","explanation_ar":"الأفضل.","options":["The sand cat has furry feet, which protect it from the hot sand.","The sand cat is cute.","Sand cats live in the desert.","The sand cat has feet."],"dok":2,"skill":"feature and job"},{"q":"Why does the writer use the headings *Plants*, *Animals* and *People*?","answer":"to group the information so it is easy to find","explanation":"Text structure.","explanation_ar":"لتنظيم المعلومات.","options":["to tell a story in order","to group the information so it is easy to find","to show the dates","to make the text a poem"],"dok":3,"skill":"text structure"},{"q":"What can you infer about water in the Empty Quarter?","answer":"It is very hard to find, so living things must save it.","explanation":"Inference.","explanation_ar":"الماء نادر جدًا.","options":["There are many rivers.","It rains every day.","It is very hard to find, so living things must save it.","Water is not important there."],"dok":3,"skill":"inference"}],"images":[{"id":"IMG-RW-L04-U5-LS2-V01","prompt":"Picture for the word 'peninsula': a map of the Arabian Peninsula"},{"id":"IMG-RW-L04-U5-LS2-V02","prompt":"Picture for the word 'quarter': a circle cut into four parts"},{"id":"IMG-RW-L04-U5-LS2-V03","prompt":"Picture for the word 'root': a desert plant with very long roots"},{"id":"IMG-RW-L04-U5-LS2-V04","prompt":"Picture for the word 'burrow': a lizard going into a hole in the sand"},{"id":"IMG-RW-L04-U5-LS2-V05","prompt":"Picture for the word 'furry': the furry paw of a sand cat"},{"id":"IMG-RW-L04-U5-LS2-V06","prompt":"Picture for the word 'hump': a camel with a big hump"},{"id":"IMG-RW-L04-U5-LS2-V07","prompt":"Picture for the word 'weave': hands weaving dark threads on a loom"},{"id":"IMG-RW-L04-U5-LS2-01","prompt":"Giant sand dunes in the Empty Quarter."},{"id":"IMG-RW-L04-U5-LS2-02","prompt":"Desert animals hiding from the heat."},{"id":"IMG-RW-L04-U5-LS2-03","prompt":"A Bedouin goat-hair tent."}],"audio":[{"id":"AUD-RW-L04-U5-LS2-V01","script":"peninsula. Saudi Arabia is on the Arabian Peninsula."},{"id":"AUD-RW-L04-U5-LS2-V02","script":"quarter. The Empty Quarter is a huge desert."},{"id":"AUD-RW-L04-U5-LS2-V03","script":"root. Some roots grow very deep."},{"id":"AUD-RW-L04-U5-LS2-V04","script":"burrow. The lizard hides in its burrow."},{"id":"AUD-RW-L04-U5-LS2-V05","script":"furry. The sand cat has furry feet."},{"id":"AUD-RW-L04-U5-LS2-V06","script":"hump. A camel's hump stores fat."},{"id":"AUD-RW-L04-U5-LS2-V07","script":"weave. Bedouin women wove tents from goat hair."},{"id":"AUD-RW-L04-U5-LS2-T1","script":"In the south of the Arabian Peninsula lies the Rub' al Khali, or the Empty Quarter. It is one of the largest sand deserts in the world. Its giant dunes roll like waves, so people call it a \"sand sea.\" But is this sea really empty? Not at all! **Hot Days, Cold Nights** In summer, the afternoon temperature can reach 50 °C. At night, however, the sand loses its heat quickly, and winter nights can be very cold. Rain is rare, and strong winds sometimes lift the sand into a sandstorm. **Plants That Save Water** Desert plants adapt to this dry environment. Some have very long roots that reach water deep under the ground. Others have small, thin leaves, so they lose less water in the hot sun. After a rare rain, seeds that have waited for years can grow and flower in just a few days. **Animals That Hide from the Heat** Many desert animals rest in burrows or in the shade during the day and come out at night, when it is cool. The scorpion hides under rocks, and the sand cat walks on furry feet that protect it from the hot sand. The spiny-tailed lizard warms itself in the morning sun and hides in its burrow when the day gets too hot. Camels can walk for days without drinking. Their humps store fat, not water, and the fat gives them energy. **People of the Desert** For hundreds of years, Bedouin families have lived in the desert with their camels and goats. They moved from place to place to find water and grass for their animals. Their tents were woven from goat hair, which gives shade from the sun and helps keep out the rain. The desert is a hard place to live, but its plants, animals and people have found clever ways to survive."},{"id":"AUD-RW-L04-U5-LS2-VID","script":"Is the Empty Quarter really empty? Let's fly over the sand sea with Saqr! In the south of the Arabian Peninsula lies the Rub' al Khali… Feature → job! Furry feet protect the sand cat from hot sand. True or false? Camels store water in their humps… FALSE! Humps store fat. Plants, animals and people – all found clever ways to survive!"}]},{"id":"RW-L04-U5-LS3","title":"Inference: reading between the lines: \"An Email from the Desert Camp\"","lesson_type":"strategy_paired_text","objectives":["make inferences (read between the lines) in an email and an article","use the formula: clue from the text + what I know = inference","explain which clue helped me and compare the email with the article"],"objectives_ar":["الاستنتاج (القراءة بين السطور) في رسالة بريد إلكتروني ومقال.","استخدام المعادلة: دليل من النص + ما أعرفه = استنتاج.","شرح الدليل الذي ساعدني ومقارنة الرسالة بالمقال."],"success_criteria":["I can find a clue that hints at something the writer doesn't say.","I can add what I know to make an inference.","I can say which clue helped me."],"success_criteria_ar":["أستطيع إيجاد دليل يلمّح إلى شيء لم يقله الكاتب.","أستطيع إضافة ما أعرفه لأصل إلى استنتاج.","أستطيع قول الدليل الذي ساعدني."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"camp","pos":"noun","ipa":"/kæmp/","definition":"a place where people stay in tents for a short time","arabic":"مخيّم","example":"My uncle's winter camp is in the desert.","image_id":"IMG-RW-L04-U5-LS3-V01","audio_id":"AUD-RW-L04-U5-LS3-V01","tier":"core"},{"word":"woolly","pos":"adjective","ipa":"/ˈwʊli/","definition":"made of soft, warm wool","arabic":"صوفي","example":"I wore a woolly hat.","image_id":"IMG-RW-L04-U5-LS3-V02","audio_id":"AUD-RW-L04-U5-LS3-V02","tier":"core"},{"word":"ginger","pos":"noun","ipa":"/ˈdʒɪndʒər/","definition":"a hot-tasting root used in food and drinks","arabic":"زنجبيل","example":"Uncle Fahd made hot ginger milk.","image_id":"IMG-RW-L04-U5-LS3-V03","audio_id":"AUD-RW-L04-U5-LS3-V03","tier":"core"},{"word":"jerboa","pos":"noun","ipa":"/dʒərˈboʊə/","definition":"a small desert animal that jumps on long back legs","arabic":"جربوع","example":"A jerboa hopped past our fire.","image_id":"IMG-RW-L04-U5-LS3-V04","audio_id":"AUD-RW-L04-U5-LS3-V04","tier":"core"},{"word":"hop","pos":"verb","ipa":"/hɑp/","definition":"to move by jumping","arabic":"يقفز","example":"The jerboa hopped across the sand.","image_id":"IMG-RW-L04-U5-LS3-V05","audio_id":"AUD-RW-L04-U5-LS3-V05","tier":"core"},{"word":"view","pos":"noun","ipa":"/vju/","definition":"what you can see from a place","arabic":"منظر","example":"The view from the top was amazing.","image_id":"IMG-RW-L04-U5-LS3-V06","audio_id":"AUD-RW-L04-U5-LS3-V06","tier":"core"},{"word":"infer","pos":"verb","ipa":"/ɪnˈfɝ/","definition":"to decide something is true from clues","arabic":"يستنتج","example":"I can infer that the night was cold.","image_id":"IMG-RW-L04-U5-LS3-V07","audio_id":"AUD-RW-L04-U5-LS3-V07","tier":"core"}],"explanation":{"text":"Writers don't always tell you everything. Sometimes they leave **clues**, and you must work out the rest. This is called **making an inference** (reading **between the lines**).\n\nUse the formula: **clue from the text + what I know = inference**. Then say **which clue** helped you: *I think … because the text says … and I know that …*\n\nA good inference is **supported** by a clue. A wild guess has **no clue** in the text. Inferences can be about **feelings, places, times, reasons** or **what will happen next**.","examples":["Clue: *I was wearing my thick jacket, a woolly hat and two pairs of socks.* + I know people wear warm clothes when it's cold → **The desert night was very cold.**","Clue: *Uncle Fahd shakes his boots before he puts them on.* + I know scorpions hide in dark places → **He checks for scorpions.**","Clue: *My legs were burning, and I had to stop three times.* + I know walking up sand is hard → **Climbing the dune was tiring.**","Clue: *a tiny animal … hopped past our fire* last night + I know many desert animals come out when it is cool → **Jerboas are active at night.**","Clue: *There are no city lights here, so the sky is full of stars.* → **City lights make stars hard to see.**","Clue: *It's soft and golden, and it comes from the dunes!* → **Omar is bringing Adam some sand (maybe in a bottle).**","Clue: *I wish you were here!* → **Omar misses Adam and enjoys the camp.**","Article clue: *Many desert animals … come out at night, when it is cool.* → it supports the jerboa inference.","Wild guess (no clue): *Omar was scared of the dark.* – nothing in the email says this."],"common_errors":["✗ Guessing with no clue. → ✓ Point to the words that helped you. (Every inference needs a clue.)","✗ Copying a sentence from the text as an inference. → ✓ Say what the sentence **shows**, not what it says. (Inference = between the lines.)","✗ I think it was cold because I like cold weather. → ✓ I think it was cold because Omar wore a thick jacket and two pairs of socks. (Use **text** clues.)","✗ Omar wear a jacket. → ✓ Omar wore a jacket. / Omar was wearing a jacket. (Past tense.)","✗ The jerboa hoped past the fire. → ✓ The jerboa hopped past the fire. (**hop → hopped** (double p).)","✗ I infer the boots is dangerous. → ✓ I infer that a scorpion might hide in the boots. (Be exact.)"],"arabic":"لا يخبرك الكاتب بكل شيء دائمًا؛ يترك أدلة وعليك أن تستنتج الباقي. هذه هي القراءة بين السطور.\n\nالمعادلة: دليل من النص + ما أعرفه = استنتاج. ثم قل: أعتقد … لأن النص يقول … وأنا أعرف أن …\n\nالاستنتاج الجيد مدعوم بدليل، أما التخمين العشوائي فلا دليل عليه في النص.\n\nمثال: عمر ارتدى معطفًا سميكًا وقبعة صوفية وجوربين ← كانت ليلة الصحراء باردة جدًا."},"video":{"script":[{"time":"00:00–00:20","narration":"Ding! A new email from Omar. But he didn't tell us everything… Let's be detectives!","on_screen":"Reading Between the Lines 🔍","visual":"A tablet screen shows a new email; a magnifying glass appears."},{"time":"00:20–01:30","narration":"Hi Adam, How are you? I'm writing from my uncle's winter camp…","on_screen":"(email)","visual":"Omar at the camp: wearing a thick jacket, shaking boots, climbing a dune, watching a jerboa, looking at stars."},{"time":"01:30–02:10","narration":"Clue + what I know = inference!","on_screen":"Clue + I know = Inference","visual":"A jacket + 'cold weather' combine into 'The night was cold.'"},{"time":"02:10–02:40","narration":"Why does Uncle Fahd shake his boots? Scorpions like dark places!","on_screen":"Clue: shakes his boots","visual":"A scorpion's shadow inside a boot."},{"time":"02:40–03:00","narration":"Can you guess Omar's gift? Soft, golden, from the dunes…","on_screen":"Sand in a bottle! 🏜️","visual":"A small bottle of golden sand with a ribbon."}],"captions_ar":["وصلت رسالة جديدة من عمر، لكنه لم يخبرنا بكل شيء… لنكن محققين!","مرحبًا آدم، كيف حالك؟ أكتب إليك من مخيم عمي الشتوي…","دليل + ما أعرفه = استنتاج!","لماذا ينفض العم فهد حذاءه؟ العقارب تحب الأماكن المظلمة!","هل تستطيع تخمين هدية عمر؟ ناعمة وذهبية ومن الكثبان…"],"voice":"Narrator: American English, detective-style male voice, speed 0.90. Omar reads his email."},"texts":[{"type":"reading","title":"An Email from the Desert Camp","body":"**To:** Adam · **From:** Omar · **Subject:** Greetings from the desert camp!\n\nHi Adam,\n\nHow are you? I'm writing from my uncle's winter camp in the desert near Riyadh. I wish you were here!\n\nWe arrived on Thursday afternoon. By the time the sun went down, I was wearing my thick jacket, a woolly hat and two pairs of socks. Uncle Fahd laughed and handed me a cup of hot ginger milk.\n\nEvery morning, Uncle Fahd shakes his boots before he puts them on, so now I do it too.\n\nYesterday, we climbed the tallest dune near the camp. Halfway up, my legs were burning, and I had to stop three times. The view from the top was worth it!\n\nLast night, a tiny animal with long back legs and a long tail hopped past our fire. My cousin Hamza said it was a jerboa.\n\nThere are no city lights here, so the sky is full of stars. I counted them until I fell asleep.\n\nCan you guess what I'm bringing you? It's soft and golden, and it comes from the dunes!\n\nSee you on Sunday,\n\nOmar","word_count":185,"audio_id":"AUD-RW-L04-U5-LS3-T1","id":"TXT-RW-L04-U5-LS3-1","genre":"letter/email","role":"paired","difficulty":"450L–600L","glossary":[{"word":"woolly","definition":"made of soft, warm wool","arabic":"صوفي"},{"word":"ginger","definition":"a hot-tasting root used in food and drinks","arabic":"زنجبيل"},{"word":"jerboa","definition":"a small desert animal that jumps on long back legs","arabic":"جربوع"}]}],"activities":[{"id":"RW-L04-U5-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read Omar's email. Choose the answer.","instructions_ar":"اقرأ رسالة عمر واختر الإجابة.","items":[{"q":"Where is Omar writing from?","answer":"his uncle's winter camp in the desert near Riyadh","explanation":"Paragraph 1.","explanation_ar":"مخيم عمه الشتوي.","options":["his school in Taif","a hotel in Jeddah","Adam's house","his uncle's winter camp in the desert near Riyadh"],"dok":1,"skill":"key details","text_id":"TXT-RW-L04-U5-LS3-1","stage":"controlled"},{"q":"When did Omar arrive at the camp?","answer":"on Thursday afternoon","explanation":"Paragraph 2.","explanation_ar":"عصر الخميس.","options":["on Sunday morning","on Friday night","last month","on Thursday afternoon"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What did Uncle Fahd give Omar?","answer":"a cup of hot ginger milk","explanation":"Paragraph 2.","explanation_ar":"كوب حليب بالزنجبيل.","options":["a thick jacket","a cup of hot ginger milk","a bottle of sand","a jerboa"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What did Omar see hopping past the fire?","answer":"a jerboa","explanation":"Paragraph 5.","explanation_ar":"جربوعًا.","options":["a falcon","a scorpion","a jerboa","a camel"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Why is the sky full of stars at the camp?","answer":"There are no city lights.","explanation":"so → effect.","explanation_ar":"لعدم وجود أضواء المدينة.","options":["It is summer.","Omar has a telescope.","There are no city lights.","There is a sandstorm."],"dok":2,"skill":"cause and effect","stage":"controlled"},{"q":"When will Omar see Adam again?","answer":"on Sunday","explanation":"Closing.","explanation_ar":"يوم الأحد.","options":["on Sunday","on Thursday","next year","tonight"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L04-U5-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Inference. Choose.","instructions_ar":"الاستنتاج: اختر.","items":[{"q":"What can you infer from *I was wearing my thick jacket, a woolly hat and two pairs of socks*?","answer":"The desert night was very cold.","explanation":"Clue + I know.","explanation_ar":"كانت الليلة باردة جدًا.","options":["Omar likes new clothes.","It was raining.","Omar was going to school.","The desert night was very cold."],"dok":2,"skill":"inference","stage":"guided"},{"q":"Why does Uncle Fahd probably shake his boots every morning?","answer":"to make sure no scorpion is hiding inside","explanation":"Clue + I know.","explanation_ar":"للتأكد من عدم وجود عقرب.","options":["to make sure no scorpion is hiding inside","to make a loud noise","to wake up Omar","to dry them"],"dok":2,"skill":"inference","stage":"guided"},{"q":"What does *my legs were burning, and I had to stop three times* tell you?","answer":"Climbing the dune was very tiring.","explanation":"Inference.","explanation_ar":"كان الصعود متعبًا.","options":["The sand was on fire.","Omar fell down the dune.","Climbing the dune was very tiring.","Omar didn't reach the top."],"dok":2,"skill":"inference","stage":"guided"},{"q":"What is Omar's gift for Adam probably?","answer":"some sand from the dunes","explanation":"soft, golden, from the dunes.","explanation_ar":"رمل من الكثبان.","options":["a jerboa","a jacket","some sand from the dunes","a cup of ginger milk"],"dok":2,"skill":"inference","stage":"guided"},{"q":"Which sentence from the ARTICLE supports the inference that jerboas are active at night?","answer":"Many desert animals rest … during the day and come out at night, when it is cool.","explanation":"Text-to-text evidence.","explanation_ar":"دليل من المقال.","options":["Camels can walk for days without drinking.","Many desert animals rest … during the day and come out at night, when it is cool.","Rain is rare.","Bedouin families moved from place to place."],"dok":3,"skill":"compare texts","stage":"guided"},{"q":"Which is a WILD GUESS, not an inference, about Omar?","answer":"Omar is afraid of camels.","explanation":"No clue in the text.","explanation_ar":"تخمين بلا دليل.","options":["Omar enjoys the camp.","Omar is afraid of camels.","Omar misses Adam.","The night was cold."],"dok":3,"skill":"evaluating inferences","stage":"guided"}]},{"id":"RW-L04-U5-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Inference Chart.","instructions_ar":"أكمل جدول الاستنتاج.","items":[{"q":"The night: clue + what I know + inference.","answer":"Clue: Omar wore a thick jacket, a woolly hat and two pairs of socks. I know: people wear warm clothes when it's cold. Inference: the desert night was very cold.","explanation":"Row 1.","explanation_ar":"الصف 1.","dok":2,"skill":"inference","stage":"freer"},{"q":"Uncle Fahd's boots: clue + what I know + inference.","answer":"Clue: he shakes his boots every morning. I know: scorpions hide in dark places. Inference: he checks for scorpions.","explanation":"Row 2.","explanation_ar":"الصف 2.","dok":2,"skill":"inference","stage":"freer"},{"q":"The tall dune: clue + what I know + inference.","answer":"Clue: Omar's legs were burning, and he stopped three times. I know: walking up sand is hard. Inference: climbing the dune was very tiring.","explanation":"Row 3.","explanation_ar":"الصف 3.","dok":2,"skill":"inference","stage":"freer"},{"q":"The gift: clue + what I know + inference.","answer":"Clue: it's soft and golden and comes from the dunes. I know: sand is soft and golden. Inference: Omar is bringing Adam some sand.","explanation":"Row 4.","explanation_ar":"الصف 4.","dok":2,"skill":"inference","stage":"freer"}]},{"id":"RW-L04-U5-LS3-A4","type":"open","stage":"production","instructions":"Writing: Infer and compare.","instructions_ar":"استنتج وقارن.","items":[{"q":"How does Omar feel about the camp? Give a clue.","answer":"He enjoys it. He says, 'I wish you were here!' and 'The view from the top was worth it!'","explanation":"Feelings + clue.","explanation_ar":"مشاعر + دليل.","dok":2,"skill":"inference","stage":"production"},{"q":"What can you infer about Omar and Adam's friendship? Give a clue.","answer":"They are good friends, because Omar writes to Adam, wishes he were there and brings him a gift.","explanation":"Inference + clue.","explanation_ar":"استنتاج + دليل.","dok":2,"skill":"inference","stage":"production"},{"q":"Which fact from the article helps you understand Omar's cold night?","answer":"'At night, … the sand loses its heat quickly, and winter nights can be very cold.'","explanation":"Text-to-text.","explanation_ar":"ربط النصين.","dok":3,"skill":"compare texts","stage":"production"},{"q":"Write a new sentence for Omar's email with a clue that lets Adam infer something.","answer":"I'm drinking lots of water and staying in the shade at noon. (Inference: the days are hot.)","explanation":"Write a clue.","explanation_ar":"اكتب دليلًا.","dok":3,"skill":"writing clues","stage":"production"}]},{"id":"RW-L04-U5-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"An Email from the Desert Camp\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “An Email from the Desert Camp”.","answer":"185 words","title":"An Email from the Desert Camp","body":"**To:** Adam · **From:** Omar · **Subject:** Greetings from the desert camp!\n\nHi Adam,\n\nHow are you? I'm writing from my uncle's winter camp in the desert near Riyadh. I wish you were here!\n\nWe arrived on Thursday afternoon. By the time the sun went down, I was wearing my thick jacket, a woolly hat and two pairs of socks. Uncle Fahd laughed and handed me a cup of hot ginger milk.\n\nEvery morning, Uncle Fahd shakes his boots before he puts them on, so now I do it too.\n\nYesterday, we climbed the tallest dune near the camp. Halfway up, my legs were burning, and I had to stop three times. The view from the top was worth it!\n\nLast night, a tiny animal with long back legs and a long tail hopped past our fire. My cousin Hamza said it was a jerboa.\n\nThere are no city lights here, so the sky is full of stars. I counted them until I fell asleep.\n\nCan you guess what I'm bringing you? It's soft and golden, and it comes from the dunes!\n\nSee you on Sunday,\n\nOmar","words":185,"limit":145}],"time_limit_sec":145},{"id":"RW-L04-U5-LS3-ORG","type":"organizer","organizer":"Inference Chart","instructions":"Organizer: For each row, write the clue from the text, what you know, and your inference.","items":[{"q":"The night (clue + I know + inference)","answer":"thick jacket, woolly hat, two pairs of socks + people wear warm clothes when it's cold → the desert night was very cold"},{"q":"Uncle Fahd's boots (clue + I know + inference)","answer":"shakes his boots every morning + scorpions hide in dark places → he checks for scorpions"},{"q":"The tall dune (clue + I know + inference)","answer":"legs burning, stopped three times + walking up sand is hard → climbing the dune was very tiring"},{"q":"The gift for Adam (clue + I know + inference)","answer":"soft, golden, from the dunes + sand is soft and golden → Omar is bringing Adam some sand"}]}],"game":{"name":"Desert Detectives","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Detective tent: a short desert scene appears; the child taps the clue words, then chooses the best inference from three options. Correct answers light a lantern in the tent; a wild guess makes the wind blow it out.","A team reads a mystery card (e.g., 'Sara drank three bottles of water and stayed in the tent at noon.').","The team highlights the clue words.","The team writes: clue + what we know = inference.","Other teams check: is there a clue, or is it a wild guess?","Clue + inference = 2 points; a wild guess = 0 points."],"data":[]},"exit_quiz":[{"q":"What does *making an inference* mean?","answer":"working something out from clues and what you know","explanation":"Inference.","explanation_ar":"الاستنتاج من الأدلة.","options":["copying a sentence","guessing with no clues","working something out from clues and what you know","reading the title only"],"dok":1,"skill":"inference"},{"q":"Who is the email FROM?","answer":"Omar","explanation":"Email header.","explanation_ar":"عمر.","options":["Adam","Omar","Uncle Fahd","Hamza"],"dok":1,"skill":"key details"},{"q":"*A jerboa **hopped** past our fire.* *Hopped* means ___.","answer":"jumped","explanation":"Hop.","explanation_ar":"قفز.","options":["flew","swam","slept","jumped"],"dok":1,"skill":"vocabulary in context"},{"q":"What is the inference formula?","answer":"clue from the text + what I know = inference","explanation":"Formula.","explanation_ar":"دليل + معرفة = استنتاج.","options":["title + picture = summary","first + last = middle","question + answer = fact","clue from the text + what I know = inference"],"dok":1,"skill":"inference"},{"q":"Which sentence about the jerboa is correct?","answer":"The jerboa hopped past the fire.","explanation":"hopped.","explanation_ar":"صحيحة.","options":["The jerboa hoped past the fire.","The jerboa hopped past the fire.","The jerboa hop past the fire yesterday.","The jerboa hopping past the fire last night."],"dok":2,"skill":"grammar"},{"q":"Which clue tells you Omar enjoyed climbing the dune?","answer":"The view from the top was worth it!","explanation":"Feelings clue.","explanation_ar":"دليل الاستمتاع.","options":["My legs were burning.","I had to stop three times.","The view from the top was worth it!","We climbed the tallest dune."],"dok":2,"skill":"inference"},{"q":"Why do you think Omar's uncle laughed when he saw Omar?","answer":"Omar was wearing so many warm clothes.","explanation":"Inference.","explanation_ar":"لأنه لبس ملابس دافئة كثيرة.","options":["Omar was wearing so many warm clothes.","Omar fell in the sand.","Omar sang a song.","Omar was very hot."],"dok":2,"skill":"inference"},{"q":"Which is the BEST supported inference?","answer":"The camp is far from the city, because there are no city lights.","explanation":"Clue-based.","explanation_ar":"استنتاج مدعوم بدليل.","options":["The camp is far from the city, because there are no city lights.","Omar doesn't like Hamza.","Uncle Fahd is a teacher.","Adam lives in Riyadh."],"dok":3,"skill":"evaluating inferences"},{"q":"How are the email and the article ALIKE?","answer":"Both show that desert nights can be cold and many animals come out at night.","explanation":"Compare.","explanation_ar":"كلاهما عن برودة الليل ونشاط الحيوانات ليلًا.","options":["Both are written by Omar.","Both have headings.","Both are about a city.","Both show that desert nights can be cold and many animals come out at night."],"dok":3,"skill":"compare texts"},{"q":"Why do writers leave clues instead of telling everything?","answer":"to make reading more interesting and let readers think","explanation":"Author's craft.","explanation_ar":"ليجعلوا القراءة ممتعة ويُشركوا القارئ.","options":["to make reading more interesting and let readers think","because they forget the facts","to make the text shorter only","because readers don't like facts"],"dok":2,"skill":"author's craft"}],"images":[{"id":"IMG-RW-L04-U5-LS3-V01","prompt":"Picture for the word 'camp': tents and a fire in the desert at night"},{"id":"IMG-RW-L04-U5-LS3-V02","prompt":"Picture for the word 'woolly': a knitted woolly hat"},{"id":"IMG-RW-L04-U5-LS3-V03","prompt":"Picture for the word 'ginger': a piece of ginger root"},{"id":"IMG-RW-L04-U5-LS3-V04","prompt":"Picture for the word 'jerboa': a jerboa with long back legs"},{"id":"IMG-RW-L04-U5-LS3-V05","prompt":"Picture for the word 'hop': a small animal mid-jump"},{"id":"IMG-RW-L04-U5-LS3-V06","prompt":"Picture for the word 'view': a view of dunes from a high place"},{"id":"IMG-RW-L04-U5-LS3-V07","prompt":"Picture for the word 'infer': a detective with a magnifying glass"},{"id":"IMG-RW-L04-U5-LS3-01","prompt":"Omar at a winter desert camp in warm clothes."},{"id":"IMG-RW-L04-U5-LS3-02","prompt":"A jerboa hopping past a campfire under the stars."},{"id":"IMG-RW-L04-U5-LS3-03","prompt":"An inference chart with clue, I know and inference columns."}],"audio":[{"id":"AUD-RW-L04-U5-LS3-V01","script":"camp. My uncle's winter camp is in the desert."},{"id":"AUD-RW-L04-U5-LS3-V02","script":"woolly. I wore a woolly hat."},{"id":"AUD-RW-L04-U5-LS3-V03","script":"ginger. Uncle Fahd made hot ginger milk."},{"id":"AUD-RW-L04-U5-LS3-V04","script":"jerboa. A jerboa hopped past our fire."},{"id":"AUD-RW-L04-U5-LS3-V05","script":"hop. The jerboa hopped across the sand."},{"id":"AUD-RW-L04-U5-LS3-V06","script":"view. The view from the top was amazing."},{"id":"AUD-RW-L04-U5-LS3-V07","script":"infer. I can infer that the night was cold."},{"id":"AUD-RW-L04-U5-LS3-T1","script":"**To:** Adam · **From:** Omar · **Subject:** Greetings from the desert camp! Hi Adam, How are you? I'm writing from my uncle's winter camp in the desert near Riyadh. I wish you were here! We arrived on Thursday afternoon. By the time the sun went down, I was wearing my thick jacket, a woolly hat and two pairs of socks. Uncle Fahd laughed and handed me a cup of hot ginger milk. Every morning, Uncle Fahd shakes his boots before he puts them on, so now I do it too. Yesterday, we climbed the tallest dune near the camp. Halfway up, my legs were burning, and I had to stop three times. The view from the top was worth it! Last night, a tiny animal with long back legs and a long tail hopped past our fire. My cousin Hamza said it was a jerboa. There are no city lights here, so the sky is full of stars. I counted them until I fell asleep. Can you guess what I'm bringing you? It's soft and golden, and it comes from the dunes! See you on Sunday, Omar"},{"id":"AUD-RW-L04-U5-LS3-VID","script":"Ding! A new email from Omar. But he didn't tell us everything… Let's be detectives! Hi Adam, How are you? I'm writing from my uncle's winter camp… Clue + what I know = inference! Why does Uncle Fahd shake his boots? Scorpions like dark places! Can you guess Omar's gift? Soft, golden, from the dunes…"}]},{"id":"RW-L04-U5-LS4","title":"Writing Skill: Email format and friendly tone","lesson_type":"writing_skill","objectives":["use the correct format for an email: header, greeting, opening, body, closing, name (and P.S.)","write in a friendly tone with contractions, questions and personal news","tell the difference between a friendly email and a formal email"],"objectives_ar":["استخدام الشكل الصحيح للبريد الإلكتروني: الترويسة والتحية والافتتاح والمتن والختام والاسم.","الكتابة بنبرة ودية باستخدام الاختصارات والأسئلة والأخبار الشخصية.","التمييز بين البريد الودي والبريد الرسمي."],"success_criteria":["I can put the parts of an email in the right order.","I can write a greeting and a closing with commas.","I can use a friendly tone for a friend and a polite, formal tone for a teacher."],"success_criteria_ar":["أستطيع ترتيب أجزاء البريد الإلكتروني ترتيبًا صحيحًا.","أستطيع كتابة التحية والختام مع الفواصل.","أستطيع استخدام نبرة ودية مع الصديق ونبرة رسمية مهذبة مع المعلم."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"subject","pos":"noun","ipa":"/ˈsʌbdʒɪkt/","definition":"the short title of an email that tells what it is about","arabic":"موضوع الرسالة","example":"Write a clear subject for your email.","image_id":"IMG-RW-L04-U5-LS4-V01","audio_id":"AUD-RW-L04-U5-LS4-V01","tier":"core"},{"word":"greeting","pos":"noun","ipa":"/ˈɡritɪŋ/","definition":"the words you use to say hello at the start","arabic":"تحية","example":"'Hi Omar,' is a friendly greeting.","image_id":"IMG-RW-L04-U5-LS4-V02","audio_id":"AUD-RW-L04-U5-LS4-V02","tier":"core"},{"word":"closing","pos":"noun","ipa":"/ˈkloʊzɪŋ/","definition":"the words before your name at the end","arabic":"عبارة الختام","example":"'Your friend,' is a closing.","image_id":"IMG-RW-L04-U5-LS4-V03","audio_id":"AUD-RW-L04-U5-LS4-V03","tier":"core"},{"word":"tone","pos":"noun","ipa":"/toʊn/","definition":"the feeling of a piece of writing (friendly, polite, serious)","arabic":"النبرة / الأسلوب","example":"Use a friendly tone with your friends.","image_id":"IMG-RW-L04-U5-LS4-V04","audio_id":"AUD-RW-L04-U5-LS4-V04","tier":"core"},{"word":"contraction","pos":"noun","ipa":"/kənˈtrækʃən/","definition":"two words joined with an apostrophe (I'm, can't)","arabic":"صيغة الاختصار","example":"'Can't' is a contraction of 'cannot'.","image_id":"IMG-RW-L04-U5-LS4-V05","audio_id":"AUD-RW-L04-U5-LS4-V05","tier":"core"},{"word":"formal","pos":"adjective","ipa":"/ˈfɔrməl/","definition":"serious and polite, for people you don't know well or for teachers","arabic":"رسمي","example":"Write a formal email to the principal.","image_id":"IMG-RW-L04-U5-LS4-V06","audio_id":"AUD-RW-L04-U5-LS4-V06","tier":"core"},{"word":"reply","pos":"noun / verb","ipa":"/rɪˈplaɪ/","definition":"an answer to a message; to answer","arabic":"رد / يرد","example":"Adam wrote a reply to Omar.","image_id":"IMG-RW-L04-U5-LS4-V07","audio_id":"AUD-RW-L04-U5-LS4-V07","tier":"core"}],"explanation":{"text":"An **email** has these parts: **To / From / Subject** (header), a **greeting** (*Hi Omar,*), an **opening line**, the **body** (short paragraphs), a **closing** (*Your friend,* / *Best wishes,*) and your **name**. You can add a **P.S.** after your name.\n\nA **friendly tone** sounds like you are talking to your friend: use **contractions** (I'm, it's, can't), **questions** (How are you? Did you…?), **exclamation marks** (but not too many!) and **personal news**. Answer your friend's questions too.\n\nA **formal tone** is for teachers and people you don't know well: *Dear Mr. Khalid,* … *Thank you for your help.* … *Best regards,*. Use full words (*I am*, *do not*) and no slang.","examples":["Subject: ***Re: Greetings from the desert camp!*** (a reply)","Friendly greeting: ***Hi Omar,*** / ***Hello Noura,*** / ***Dear Grandma,***","Opening line: ***Thanks so much for your email!*** / ***How are you?***","Answer your friend: ***I'm guessing your gift is sand from the dunes. Am I right?***","Ask questions: ***Did it come close to the fire? Was it scared of you?***","Personal news: ***On Friday, my family and I went to the park, and we ate hot grilled corn.***","Friendly closing: ***Your friend,*** / ***See you soon,*** / ***Take care,***","Formal: ***Dear Mr. Khalid, I am writing to ask about the science trip. Best regards, Adam***","P.S.: ***P.S. Don't forget to shake your boots!***"],"common_errors":["✗ Hi Omar → ✓ Hi Omar, (Put a **comma** after the greeting.)","✗ Your friend Adam → ✓ Your friend, (new line) Adam (Comma after the closing; name on the next line.)","✗ No subject. → ✓ Subject: Greetings from the desert camp! (Always write a subject.)","✗ Hey teacher!!! whats up → ✓ Dear Mr. Khalid, (Use a **formal** tone for teachers.)","✗ Im happy. → ✓ I'm happy. (Contractions need an **apostrophe**.)","✗ One long paragraph. → ✓ Short paragraphs, one topic each. (Easy to read.)","✗ Too many exclamation marks!!!!! → ✓ One is enough! (Don't overuse them.)"],"arabic":"أجزاء البريد: الترويسة (إلى/من/الموضوع)، والتحية، وجملة افتتاحية، والمتن في فقرات قصيرة، والختام، والاسم، ويمكن إضافة ملاحظة P.S.\n\nالنبرة الودية: اختصارات (I'm, can't)، وأسئلة للصديق، وعلامات تعجب دون إفراط، وأخبار شخصية، والإجابة عن أسئلة الصديق.\n\nالنبرة الرسمية للمعلمين ومن لا نعرفهم جيدًا: Dear Mr. Khalid … Best regards، وكلمات كاملة دون عامية.\n\nانتبه للفاصلة بعد التحية وبعد عبارة الختام، وللفاصلة العليا في الاختصارات."},"video":{"script":[{"time":"00:00–00:20","narration":"Omar sent an email from the desert. Now Adam is writing back!","on_screen":"Writing an Email ✉️","visual":"Adam types on a tablet in his blue wheelchair."},{"time":"00:20–01:15","narration":"Hi Omar, Thanks so much for your email!…","on_screen":"(Adam's reply)","visual":"The email appears part by part with labels: header, greeting, opening, body, closing, name, P.S."},{"time":"01:15–02:00","narration":"Friendly tone: contractions, questions and news! I can't believe you saw a jerboa!","on_screen":"I'm · can't · it's · I'll","visual":"Words join together with an apostrophe."},{"time":"02:00–02:40","narration":"Writing to a teacher? Use a formal tone: Dear Mr. Khalid… Best regards.","on_screen":"Friendly vs. formal","visual":"Two emails side by side: one to Omar, one to Mr. Khalid."},{"time":"02:40–03:00","narration":"Don't forget the commas after the greeting and the closing. Click send!","on_screen":"Send 📤","visual":"The email flies away from the tablet."}],"captions_ar":["أرسل عمر رسالة من الصحراء، والآن يكتب آدم الرد!","مرحبًا عمر، شكرًا جزيلًا على رسالتك!…","النبرة الودية: اختصارات وأسئلة وأخبار! لا أصدق أنك رأيت جربوعًا!","تكتب إلى معلم؟ استخدم نبرة رسمية: Dear Mr. Khalid… Best regards.","لا تنسَ الفاصلة بعد التحية وعبارة الختام. اضغط إرسال!"],"voice":"Narrator: American English, friendly female teacher, speed 0.90. Adam reads his reply."},"texts":[{"type":"model","title":"Adam's Reply","body":"**To:** Omar · **From:** Adam · **Subject:** Re: Greetings from the desert camp!\n\nHi Omar,\n\nThanks so much for your email! It made me feel like I was at the camp with you.\n\nI can't believe you saw a jerboa! I've only seen one in a book. Did it come close to the fire? Was it scared of you?\n\nHere in Taif, it's been rainy and cool all week. On Friday, my family and I went to the park, and we ate hot grilled corn. It was delicious!\n\nI'm guessing your gift is sand from the dunes. Am I right? I'll keep it on my desk next to my falcon picture.\n\nHave a safe trip home, and say hello to Hamza for me.\n\nYour friend,\n\nAdam\n\nP.S. Don't forget to shake your boots!","word_count":132,"audio_id":"AUD-RW-L04-U5-LS4-T1","id":"TXT-RW-L04-U5-LS4-1","genre":"model text","role":"model","difficulty":"450L–600L","glossary":[],"annotations":["**Header:** *To*, *From* and a short **Subject** that tells what the email is about (*Re:* = a reply).","**Greeting:** *Hi Omar,* – a friendly greeting with a **comma**.","**Opening line:** *Thanks so much for your email!* – connects to the friend's message.","**Body:** short paragraphs, each with **one topic**: the jerboa, news from Taif, the gift.","**Friendly tone:** contractions (*I can't, I've, it's, I'll*), questions to the reader (*Did it come close…?*), exclamation marks (but not too many!) and personal news.","**Closing + name:** *Have a safe trip home… Your friend, Adam* – a kind wish, a closing with a comma and your name.","**P.S.** (post script): a short extra message after the name."]}],"activities":[{"id":"RW-L04-U5-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read Adam's reply. Choose the best answer.","instructions_ar":"اقرأ رد آدم واختر أفضل إجابة.","items":[{"q":"What does *Re:* in Adam's subject line show?","answer":"The email is a reply.","explanation":"Re: = reply.","explanation_ar":"أنه رد.","options":["The email is a reply.","The email is very short.","The email is from a teacher.","The email is late."],"dok":1,"skill":"email format","stage":"controlled"},{"q":"What has the weather been like in Taif?","answer":"rainy and cool","explanation":"Paragraph 3.","explanation_ar":"ممطر ولطيف.","options":["hot and dry","rainy and cool","snowy","very windy and sandy"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What did Adam's family eat at the park?","answer":"hot grilled corn","explanation":"Paragraph 3.","explanation_ar":"ذرة مشوية.","options":["ginger milk","dates","hot grilled corn","ice cream"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does Adam think Omar's gift is?","answer":"sand from the dunes","explanation":"Paragraph 4.","explanation_ar":"رمل من الكثبان.","options":["a toy jerboa","sand from the dunes","a woolly hat","a falcon picture"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Why does Adam ask *Did it come close to the fire?*","answer":"to show interest and keep the conversation going","explanation":"Friendly tone.","explanation_ar":"ليُظهر اهتمامه.","options":["because he is angry","to end the email","to give news about Taif","to show interest and keep the conversation going"],"dok":2,"skill":"tone","stage":"controlled"},{"q":"Why does Adam's P.S. say *Don't forget to shake your boots!*?","answer":"It is a friendly joke linked to Omar's email.","explanation":"Connection.","explanation_ar":"دعابة ودية مرتبطة برسالة عمر.","options":["Adam lost his boots.","Omar asked for boots.","It is a friendly joke linked to Omar's email.","It is part of the subject."],"dok":3,"skill":"inference","stage":"controlled"}]},{"id":"RW-L04-U5-LS4-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Email format and tone. Choose.","instructions_ar":"شكل البريد والنبرة: اختر.","items":[{"q":"Which greeting for Omar is written correctly?","answer":"Hi Omar,","explanation":"Capital + comma.","explanation_ar":"صحيحة.","options":["Hi Omar,","Hi Omar","hi omar,","Hi, Omar."],"dok":1,"skill":"email format","stage":"guided"},{"q":"Which closing to a friend is written correctly?","answer":"Your friend,","explanation":"Comma after the closing.","explanation_ar":"صحيحة.","options":["Your friend","your Friend.","Your friend,","Your friend!"],"dok":1,"skill":"email format","stage":"guided"},{"q":"Which sentence has a FRIENDLY tone?","answer":"I can't wait to see your photos!","explanation":"Friendly.","explanation_ar":"ودية.","options":["I am writing to request information.","Please find the report attached.","I would like to thank you for your consideration.","I can't wait to see your photos!"],"dok":2,"skill":"tone","stage":"guided"},{"q":"Which greeting should you use in an email to your teacher, Mr. Khalid?","answer":"Dear Mr. Khalid,","explanation":"Formal.","explanation_ar":"رسمية.","options":["Hey Khalid!!!","Yo teacher,","Hi buddy,","Dear Mr. Khalid,"],"dok":1,"skill":"formal tone","stage":"guided"},{"q":"Which contraction about Adam's surprise is written correctly?","answer":"I can't believe it!","explanation":"Apostrophe.","explanation_ar":"صحيحة.","options":["I can't believe it!","I cant believe it!","I ca'nt believe it!","I can,t believe it!"],"dok":2,"skill":"contractions","stage":"guided"},{"q":"Which order of email parts is correct?","answer":"subject → greeting → opening → body → closing → name → P.S.","explanation":"Format.","explanation_ar":"الترتيب الصحيح.","options":["greeting → name → body → subject → closing","subject → greeting → opening → body → closing → name → P.S.","closing → body → greeting → subject → name","P.S. → subject → greeting → body → closing"],"dok":2,"skill":"email format","stage":"guided"}]},{"id":"RW-L04-U5-LS4-A3","type":"sequence","stage":"freer","instructions":"Put in order: Build the email parts.","instructions_ar":"ابنِ أجزاء البريد.","items":[{"q":"Put Noura's email to Layla about the farm in order.","answer":"Subject: Our trip to the farm → Hi Layla, → How are you? → Last week, we visited my uncle's farm. → Write back soon, → Noura","explanation":"Subject → greeting → opening → body → closing → name.","explanation_ar":"الترتيب الصحيح للبريد.","stage":"freer","parts":["Noura","Last week, we visited my uncle's farm.","Subject: Our trip to the farm","How are you?","Hi Layla,","Write back soon,"],"target":["Subject: Our trip to the farm","Hi Layla,","How are you?","Last week, we visited my uncle's farm.","Write back soon,","Noura"]},{"q":"Build the formal opening of Adam's email to Mr. Khalid.","answer":"Dear Mr. Khalid, → I am writing → to ask about → the science trip.","explanation":"Formal greeting + full words.","explanation_ar":"تحية رسمية + كلمات كاملة.","stage":"freer","parts":["Dear Mr. Khalid,","the science trip.","to ask about","I am writing"],"target":["Dear Mr. Khalid,","I am writing","to ask about","the science trip."]},{"q":"Build a friendly sentence about Omar's camp photos.","answer":"I can't wait → to see → the photos → of the camp!","explanation":"Friendly: contraction + exclamation.","explanation_ar":"ودية: اختصار + تعجب.","stage":"freer","parts":["the photos","I can't wait","of the camp!","to see"],"target":["I can't wait","to see","the photos","of the camp!"]},{"q":"Build Noura's P.S. to Layla about her cat.","answer":"P.S. → Say hello → to your cat → Qamar!","explanation":"P.S. after the name.","explanation_ar":"P.S. بعد الاسم.","stage":"freer","parts":["Say hello","Qamar!","P.S.","to your cat"],"target":["P.S.","Say hello","to your cat","Qamar!"]}]},{"id":"RW-L04-U5-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write parts of an email.","instructions_ar":"اكتب أجزاء البريد.","items":[{"q":"Write a subject line and a friendly greeting for an email to your cousin about a desert trip.","answer":"Subject: My first night in the desert! / Hi Hamza,","explanation":"Subject + greeting.","explanation_ar":"الموضوع + التحية.","dok":1,"skill":"email format","stage":"production"},{"q":"Write a friendly opening line and one question for your cousin.","answer":"How are you? Have you ever slept in a tent?","explanation":"Opening + question.","explanation_ar":"افتتاح + سؤال.","dok":2,"skill":"tone","stage":"production"},{"q":"Change this formal sentence to a friendly one: *I am very pleased to receive your message.*","answer":"I'm so happy you wrote to me!","explanation":"Formal → friendly.","explanation_ar":"رسمي ← ودي.","dok":2,"skill":"tone","stage":"production"},{"q":"Write a friendly closing, your name and a P.S.","answer":"See you soon, (new line) Sami (new line) P.S. I saved you some dates from the camp!","explanation":"Closing + name + P.S.","explanation_ar":"ختام + اسم + P.S.","dok":2,"skill":"email format","stage":"production"}]}],"game":{"name":"Inbox Sort","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Inbox: sentences drop into the screen; the child swipes them into the FRIEND or TEACHER inbox, then drags email parts into the right order to 'send' the email. A correctly built email flies away with a whoosh.","Teams get a mixed pile of sentences and email parts.","They sort sentences into FRIEND (friendly) and TEACHER (formal) inboxes.","Then they build one complete email for each inbox in the correct order.","Other teams check commas, apostrophes and tone.","Each correct sentence = 1 point; each complete email = 5 points."],"data":[]},"exit_quiz":[{"q":"What does the *subject* of an email tell you?","answer":"what the email is about","explanation":"Subject.","explanation_ar":"موضوع الرسالة.","options":["what the email is about","who wrote it","the date","the closing"],"dok":1,"skill":"email format"},{"q":"Which is a CONTRACTION?","answer":"I'm","explanation":"Contraction.","explanation_ar":"I'm.","options":["I am","my","me","I'm"],"dok":1,"skill":"contractions"},{"q":"Which word means *the feeling of a piece of writing*?","answer":"tone","explanation":"Tone.","explanation_ar":"النبرة.","options":["tone","subject","reply","greeting"],"dok":1,"skill":"vocabulary"},{"q":"Where does the P.S. go?","answer":"after your name","explanation":"Format.","explanation_ar":"بعد الاسم.","options":["before the greeting","after your name","in the subject","in the first line"],"dok":1,"skill":"email format"},{"q":"Which greeting to Grandma is written correctly?","answer":"Dear Grandma,","explanation":"Capitals + comma.","explanation_ar":"صحيحة.","options":["dear grandma","Dear Grandma,","Dear Grandma","Dear, Grandma."],"dok":2,"skill":"email format"},{"q":"Which sentence would fit a FORMAL email to the school principal?","answer":"Thank you for your help with the science fair.","explanation":"Formal.","explanation_ar":"رسمية.","options":["Thanks a million, you're the best!!!","Hey, what's up?","Thank you for your help with the science fair.","See ya!"],"dok":2,"skill":"formal tone"},{"q":"Why does a friendly email often include questions?","answer":"to show interest and invite the friend to write back","explanation":"Purpose.","explanation_ar":"لإظهار الاهتمام ودعوة الصديق للرد.","options":["to make it formal","to fill the page","to show interest and invite the friend to write back","to replace the greeting"],"dok":2,"skill":"tone"},{"q":"Which sentence about the desert camp uses a contraction correctly?","answer":"It's cold at night in the desert.","explanation":"It's = it is.","explanation_ar":"صحيحة.","options":["Its' cold at night in the desert.","Its cold at night in the desert.","It,s cold at night in the desert.","It's cold at night in the desert."],"dok":2,"skill":"contractions"},{"q":"Omar asked Adam, *Can you guess what I'm bringing you?* What should a good reply do?","answer":"answer the question","explanation":"Respond.","explanation_ar":"الإجابة عن السؤال.","options":["ignore the question","change the subject only","answer the question","end the email"],"dok":3,"skill":"replying"},{"q":"Which is the BEST subject for an email about a desert trip?","answer":"My amazing night in the desert!","explanation":"Clear subject.","explanation_ar":"الأفضل.","options":["Hi","Email","Read this now!!!","My amazing night in the desert!"],"dok":3,"skill":"email format"}],"images":[{"id":"IMG-RW-L04-U5-LS4-V01","prompt":"Picture for the word 'subject': an email subject line highlighted"},{"id":"IMG-RW-L04-U5-LS4-V02","prompt":"Picture for the word 'greeting': a hand waving hello"},{"id":"IMG-RW-L04-U5-LS4-V03","prompt":"Picture for the word 'closing': the end of a letter with a signature"},{"id":"IMG-RW-L04-U5-LS4-V04","prompt":"Picture for the word 'tone': two faces: a smiling one and a serious one"},{"id":"IMG-RW-L04-U5-LS4-V05","prompt":"Picture for the word 'contraction': I + am = I'm with an apostrophe"},{"id":"IMG-RW-L04-U5-LS4-V06","prompt":"Picture for the word 'formal': a neat formal letter"},{"id":"IMG-RW-L04-U5-LS4-V07","prompt":"Picture for the word 'reply': a reply arrow on a screen"},{"id":"IMG-RW-L04-U5-LS4-01","prompt":"Adam typing an email reply."},{"id":"IMG-RW-L04-U5-LS4-02","prompt":"A labelled email."},{"id":"IMG-RW-L04-U5-LS4-03","prompt":"Two envelopes for friendly and formal emails."}],"audio":[{"id":"AUD-RW-L04-U5-LS4-V01","script":"subject. Write a clear subject for your email."},{"id":"AUD-RW-L04-U5-LS4-V02","script":"greeting. 'Hi Omar,' is a friendly greeting."},{"id":"AUD-RW-L04-U5-LS4-V03","script":"closing. 'Your friend,' is a closing."},{"id":"AUD-RW-L04-U5-LS4-V04","script":"tone. Use a friendly tone with your friends."},{"id":"AUD-RW-L04-U5-LS4-V05","script":"contraction. 'Can't' is a contraction of 'cannot'."},{"id":"AUD-RW-L04-U5-LS4-V06","script":"formal. Write a formal email to the principal."},{"id":"AUD-RW-L04-U5-LS4-V07","script":"reply. Adam wrote a reply to Omar."},{"id":"AUD-RW-L04-U5-LS4-T1","script":"**To:** Omar · **From:** Adam · **Subject:** Re: Greetings from the desert camp! Hi Omar, Thanks so much for your email! It made me feel like I was at the camp with you. I can't believe you saw a jerboa! I've only seen one in a book. Did it come close to the fire? Was it scared of you? Here in Taif, it's been rainy and cool all week. On Friday, my family and I went to the park, and we ate hot grilled corn. It was delicious! I'm guessing your gift is sand from the dunes. Am I right? I'll keep it on my desk next to my falcon picture. Have a safe trip home, and say hello to Hamza for me. Your friend, Adam P.S. Don't forget to shake your boots!"},{"id":"AUD-RW-L04-U5-LS4-VID","script":"Omar sent an email from the desert. Now Adam is writing back! Hi Omar, Thanks so much for your email!… Friendly tone: contractions, questions and news! I can't believe you saw a jerboa! Writing to a teacher? Use a formal tone: Dear Mr. Khalid… Best regards. Don't forget the commas after the greeting and the closing. Click send!"}]},{"id":"RW-L04-U5-LS5","title":"Writing Workshop: An email to a friend describing a desert trip","lesson_type":"writing_workshop","objectives":["plan an email to a friend about a desert trip with the Email Planner","write an 80–100-word email with the correct format, a friendly tone and two or three details from the trip","revise, edit and 'send' the email to a classmate, who writes a short reply"],"objectives_ar":["التخطيط لبريد إلكتروني إلى صديق عن رحلة صحراوية بمخطط البريد.","كتابة بريد من 80–100 كلمة بالشكل الصحيح ونبرة ودية وتفصيلين أو ثلاثة من الرحلة.","تحسين البريد وتدقيقه و«إرساله» إلى زميل يكتب ردًا قصيرًا."],"success_criteria":["My email has a subject, a greeting, an opening, a body, a closing and my name.","I described two or three events from the trip with details and feelings.","I used a friendly tone with contractions and a question for my friend."],"success_criteria_ar":["بريدي فيه موضوع وتحية وافتتاح ومتن وختام واسمي.","وصفت حدثين أو ثلاثة من الرحلة بالتفاصيل والمشاعر.","استخدمت نبرة ودية مع اختصارات وسؤال لصديقي."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"sway","pos":"verb","ipa":"/sweɪ/","definition":"to move slowly from side to side","arabic":"يتمايل","example":"The camel swayed as it walked.","image_id":"IMG-RW-L04-U5-LS5-V01","audio_id":"AUD-RW-L04-U5-LS5-V01","tier":"core"},{"word":"sandboard","pos":"noun","ipa":"/ˈsændˌbɔrd/","definition":"a board for sliding down sand dunes","arabic":"لوح التزلج على الرمل","example":"We slid down the dune on a sandboard.","image_id":"IMG-RW-L04-U5-LS5-V02","audio_id":"AUD-RW-L04-U5-LS5-V02","tier":"core"},{"word":"slide","pos":"verb","ipa":"/slaɪd/","definition":"to move smoothly over a surface (past: slid)","arabic":"ينزلق","example":"Faris slid down the dune.","image_id":"IMG-RW-L04-U5-LS5-V03","audio_id":"AUD-RW-L04-U5-LS5-V03","tier":"core"},{"word":"trainer","pos":"noun","ipa":"/ˈtreɪnər/","definition":"a person who teaches animals or people a skill","arabic":"مدرّب","example":"The falcon trainer wore a thick glove.","image_id":"IMG-RW-L04-U5-LS5-V04","audio_id":"AUD-RW-L04-U5-LS5-V04","tier":"core"},{"word":"glove","pos":"noun","ipa":"/ɡlʌv/","definition":"something you wear on your hand","arabic":"قفاز","example":"The falcon landed on the glove.","image_id":"IMG-RW-L04-U5-LS5-V05","audio_id":"AUD-RW-L04-U5-LS5-V05","tier":"core"},{"word":"sunset","pos":"noun","ipa":"/ˈsʌnˌsɛt/","definition":"the time when the sun goes down","arabic":"غروب الشمس","example":"The sunset was orange and pink.","image_id":"IMG-RW-L04-U5-LS5-V06","audio_id":"AUD-RW-L04-U5-LS5-V06","tier":"core"},{"word":"weekend","pos":"noun","ipa":"/ˈwikˌɛnd/","definition":"the days when there is no school or work (in Saudi Arabia: Friday and Saturday)","arabic":"عطلة نهاية الأسبوع","example":"We went camping for the weekend.","image_id":"IMG-RW-L04-U5-LS5-V07","audio_id":"AUD-RW-L04-U5-LS5-V07","tier":"core"}],"explanation":{"text":"Your email tells a friend about **your desert trip**. Use all the **email parts**: To / Subject, a friendly **greeting**, an **opening line**, a **body** of two short paragraphs, a **question** for your friend, a **closing**, your **name** and a **P.S.** if you like.\n\nIn the body, choose **two or three events** from the photo cards. For each event, say **what happened**, add **one detail** and **one feeling**: *I rode a camel for the first time. It was so tall that I held on tight!*\n\nKeep a **friendly tone**: contractions (I'm, it's, you'd), exclamation marks (not too many), and **talk to your friend**: *Have you ever…? I think you'd love it!* Keep it **80–100 words** – emails are short!","examples":["Subject: ***You won't believe my desert weekend!***","Greeting + opening: ***Hi Layla, How are you? I just got back from a weekend at a desert camp, and I have so much to tell you!***","Event + detail + feeling: ***On Saturday morning, I rode a camel for the first time. It was so tall that I held on tight!***","Time transition: ***In the afternoon, … / At night, …***","Event 2: ***Faris and I slid down a huge dune on a sandboard. We laughed all the way down.***","Event 3: ***At night, we sat around the fire and drank hot milk while my dad told stories.***","Question for your friend: ***Have you ever been to a desert camp?***","Closing: ***Write back soon, Noura***","P.S.: ***P.S. I took a photo of the sunset for you!***"],"common_errors":["✗ Listing everything you did. → ✓ Choose two or three events and add details. (Details > a long list.)","✗ I ride a camel yesterday. → ✓ I rode a camel yesterday. (Use the **past tense** for the trip.)","✗ We slided down the dune. → ✓ We slid down the dune. (Irregular past: **slid**.)","✗ No question for your friend. → ✓ Have you ever been to a desert camp? (Talk **to** your friend.)","✗ Writing 200 words. → ✓ Keep it 80–100 words. (Emails are short.)","✗ Hi Layla (no comma) → ✓ Hi Layla, (Comma after the greeting.)","✗ Dear Ms. Layla, I am writing to inform you… → ✓ Hi Layla, How are you? (Friendly tone for a friend.)"],"arabic":"استخدم كل أجزاء البريد: الموضوع والتحية والافتتاح والمتن (فقرتان قصيرتان) وسؤال لصديقك والختام واسمك وP.S.\n\nاختر حدثين أو ثلاثة من بطاقات الصور، ولكل حدث: ماذا حدث + تفصيل + شعور.\n\nحافظ على النبرة الودية: اختصارات وعلامات تعجب قليلة وحديث مباشر مع صديقك، واجعل البريد 80–100 كلمة.\n\nاستخدم الماضي لأحداث الرحلة، وانتبه للأفعال الشاذة مثل rode وslid."},"video":{"script":[{"time":"00:00–00:20","narration":"Noura just came back from the desert. She can't wait to tell Layla!","on_screen":"An Email About My Trip ✉️🏜️","visual":"Noura looks at photos on a tablet."},{"time":"00:20–01:00","narration":"Choose two or three photos: the camel ride, sandboarding, the falcon show, the night fire…","on_screen":"Photo cards 📸","visual":"Five photo cards fan out; Noura picks three."},{"time":"01:00–01:45","narration":"Plan with the Email Planner: subject, greeting, two short paragraphs, a question and a closing.","on_screen":"Email Planner","visual":"A planner fills in box by box."},{"time":"01:45–02:35","narration":"On Saturday morning, I rode a camel for the first time. It was so tall that I held on tight!","on_screen":"Event + detail + feeling","visual":"Noura on a swaying camel, then sliding down a dune with Faris."},{"time":"02:35–03:00","narration":"Check the commas, count the words and press send. Then wait for a reply!","on_screen":"Send 📤 · Reply 📥","visual":"The email flies to Layla, who smiles and starts typing."}],"captions_ar":["عادت نورة للتو من الصحراء ولا تطيق الانتظار لتخبر ليلى!","اختر صورتين أو ثلاثًا: ركوب الجمل، التزلج على الرمل، عرض الصقور، نار الليل…","خطّط بمخطط البريد: الموضوع والتحية وفقرتان قصيرتان وسؤال وختام.","صباح السبت ركبت جملًا لأول مرة، وكان طويلًا جدًا فتمسّكت بقوة!","راجع الفواصل وعُدّ الكلمات واضغط إرسال، ثم انتظر الرد!"],"voice":"Narrator: American English, warm female voice, speed 0.90. Noura reads her email."},"texts":[{"type":"model","title":"Desert Trip Photo Cards","body":"**Photo 1 – Arriving at the camp** · Friday afternoon · tents in a circle · the sun going down · the sky turns orange and pink\n\n**Photo 2 – A camel ride** · Saturday morning · the camel is very tall · it walks slowly and sways · hold on tight!\n\n**Photo 3 – Sandboarding** · a huge dune · climb up slowly, slide down fast · sand in your shoes · lots of laughing\n\n**Photo 4 – The falcon show** · a trainer with a thick glove · the falcon flies very fast · it lands on the glove · everyone claps\n\n**Photo 5 – Night at the camp** · a fire in the middle · hot milk or tea · stories from the grown-ups · thousands of stars","word_count":106,"audio_id":"AUD-RW-L04-U5-LS5-T1","id":"TXT-RW-L04-U5-LS5-1","genre":"photo cards","role":"model","difficulty":"450L–600L","glossary":[],"annotations":["Choose **two or three** photos for the body of your email.","Turn the notes into **full sentences** with your own feelings: *It was so tall that I held on tight!*","Remember the email parts and a **friendly tone**: contractions, a question for your friend and a P.S."]}],"activities":[{"id":"RW-L04-U5-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the photo cards and Noura's model. Choose the answer.","instructions_ar":"اقرأ بطاقات الصور ونموذج نورة واختر الإجابة.","items":[{"q":"What color does the sky turn in Photo 1?","answer":"orange and pink","explanation":"Photo 1.","explanation_ar":"برتقالي ووردي.","options":["orange and pink","grey and black","green and blue","white"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How does the camel walk in Photo 2?","answer":"slowly, and it sways","explanation":"Photo 2.","explanation_ar":"ببطء ويتمايل.","options":["slowly, and it sways","very fast, and it jumps","backward","it doesn't walk"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where does the falcon land in Photo 4?","answer":"on the trainer's thick glove","explanation":"Photo 4.","explanation_ar":"على قفاز المدرب.","options":["on a tent","on the trainer's thick glove","on the camel","on the fire"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who went sandboarding with Noura?","answer":"Faris","explanation":"Model.","explanation_ar":"فارس.","options":["Layla","Omar","Dana","Faris"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What did Noura's family drink at night?","answer":"hot milk","explanation":"Model.","explanation_ar":"حليبًا ساخنًا.","options":["cold juice","hot milk","lemonade","coffee with cardamom"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Why does Noura write *I have so much to tell you!*?","answer":"to show she is excited and to start her news","explanation":"Opening.","explanation_ar":"لتُظهر حماسها.","options":["to end the email","to ask for help","to show she is excited and to start her news","to give the date"],"dok":2,"skill":"tone","stage":"controlled"}]},{"id":"RW-L04-U5-LS5-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Plan the email. Choose.","instructions_ar":"خطّط للبريد: اختر.","items":[{"q":"Which is the BEST subject for an email about a desert weekend?","answer":"You won't believe my desert weekend!","explanation":"Clear + interesting.","explanation_ar":"الأفضل.","options":["Hello","Email number 2","You won't believe my desert weekend!","Sand"],"dok":1,"skill":"email format","stage":"guided"},{"q":"Which sentence gives an event, a detail AND a feeling?","answer":"I rode a camel for the first time. It was so tall that I held on tight!","explanation":"Event + detail + feeling.","explanation_ar":"حدث + تفصيل + شعور.","options":["I rode a camel for the first time. It was so tall that I held on tight!","I rode a camel.","Camels are animals.","There was a camel."],"dok":2,"skill":"details","stage":"guided"},{"q":"Which sentence about sandboarding uses the past tense correctly?","answer":"Faris and I slid down a huge dune.","explanation":"slid.","explanation_ar":"صحيحة.","options":["Faris and I slided down a huge dune.","Faris and I slid down a huge dune.","Faris and I slide down a huge dune yesterday.","Faris and I sliding down a huge dune."],"dok":2,"skill":"grammar","stage":"guided"},{"q":"Which question is BEST to ask your friend at the end of the body?","answer":"Have you ever been to a desert camp?","explanation":"Talk to your friend.","explanation_ar":"السؤال الأفضل.","options":["What is a camel?","Why is sand yellow?","Is today Monday?","Have you ever been to a desert camp?"],"dok":2,"skill":"tone","stage":"guided"},{"q":"Which closing is BEST for an email to a friend?","answer":"Write back soon,","explanation":"Friendly closing.","explanation_ar":"الختام الأفضل.","options":["Best regards,","Yours faithfully,","The end.","Write back soon,"],"dok":2,"skill":"email format","stage":"guided"},{"q":"Your email is 190 words long. What should you do?","answer":"Choose fewer events and cut extra details.","explanation":"80–100 words.","explanation_ar":"اختصر.","options":["Add more events.","Remove the greeting.","Choose fewer events and cut extra details.","Write it in capital letters."],"dok":3,"skill":"revising","stage":"guided"}]},{"id":"RW-L04-U5-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your email with the Email Planner.","instructions_ar":"خطط لبريدك بمخطط البريد.","items":[{"q":"Header and greeting – who is it to, and what is the subject?","answer":"To: Omar · From: Sami · Subject: The best camp ever! – Hi Omar,","explanation":"Header + greeting.","explanation_ar":"الترويسة + التحية.","dok":1,"skill":"planning","stage":"freer"},{"q":"Body paragraph 1 – one event + a detail + a feeling (notes).","answer":"Friday – arrived at sunset – sky orange and pink – amazing","explanation":"Event 1.","explanation_ar":"الحدث 1.","dok":2,"skill":"planning","stage":"freer"},{"q":"Body paragraph 2 – one or two more events (notes).","answer":"falcon show – flew very fast, landed on the glove – everyone clapped; night – thousands of stars","explanation":"Event 2.","explanation_ar":"الحدث 2.","dok":2,"skill":"planning","stage":"freer"},{"q":"A question for your friend, the closing and a P.S. (notes).","answer":"Have you ever seen a falcon up close? – See you soon, Sami – P.S. I bought you a falcon key ring!","explanation":"Question + closing + P.S.","explanation_ar":"سؤال + ختام + P.S.","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L04-U5-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write, revise, edit and send your email.","instructions_ar":"اكتب بريدك وحسّنه ودققه وأرسله.","items":[{"q":"Write your header, greeting and opening line.","answer":"To: Omar · From: Sami · Subject: The best camp ever! Hi Omar, How are you? I'm back from the desert, and it was amazing!","explanation":"Opening part.","explanation_ar":"الجزء الأول.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your body: two or three events with details and feelings.","answer":"We arrived on Friday at sunset, and the sky turned orange and pink. On Saturday, we watched a falcon show. The falcon flew so fast that I couldn't follow it with my eyes! At night, there were thousands of stars.","explanation":"Body.","explanation_ar":"المتن.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your question, closing, name and P.S.","answer":"Have you ever seen a falcon up close? See you soon, (new line) Sami (new line) P.S. I bought you a falcon key ring!","explanation":"Ending.","explanation_ar":"النهاية.","dok":2,"skill":"writing","stage":"production"},{"q":"Write the short reply your partner sent you (two sentences).","answer":"Hi Sami, Your trip sounds amazing! No, I've never seen a falcon up close – I can't wait to see your photos.","explanation":"Reply.","explanation_ar":"الرد.","dok":2,"skill":"replying","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L04-U5-LS5-ORG","type":"organizer","organizer":"Email Planner","instructions":"Organizer: Use the photo cards. Write short notes in each box.","items":[{"q":"Header – To, From, Subject","answer":"To: Layla · From: Noura · Subject: You won't believe my desert weekend!"},{"q":"Greeting + opening line","answer":"Hi Layla, – How are you? just got back from a desert camp"},{"q":"Body paragraph 1 – event + detail + feeling","answer":"Saturday morning – camel ride – so tall – held on tight"},{"q":"Body paragraph 2 – event + detail + feeling","answer":"afternoon – sandboarding with Faris – laughed; night – fire, hot milk, Dad's stories"},{"q":"A question for my friend","answer":"Have you ever been to a desert camp?"},{"q":"Closing + name + P.S.","answer":"Write back soon, Noura – P.S. photo of the sunset"}]},{"id":"RW-L04-U5-LS5-WR","type":"writing","instructions":"Writing: Write an email (80–100 words) to a friend about a trip to a desert camp. Use the photo cards. Include a subject, a greeting, an opening, two or three events with details and feelings, a question for your friend, a closing and your name. Write an email (80–100 words) to a friend about a trip to a desert camp. Use the photo cards. Include a subject, a greeting, an opening, two or three events with details and feelings, a question for your friend, a closing and your name.","instructions_ar":"اكتب بريدًا إلكترونيًا (80–100 كلمة) إلى صديق عن رحلة إلى مخيم صحراوي مستعينًا ببطاقات الصور، فيه موضوع وتحية وافتتاح وحدثان أو ثلاثة بتفاصيل ومشاعر وسؤال لصديقك وختام واسمك.","prompt":"Write an email (80–100 words) to a friend about a trip to a desert camp. Use the photo cards. Include a subject, a greeting, an opening, two or three events with details and feelings, a question for your friend, a closing and your name.","checklist":["My email has To, From and a clear subject.","I wrote a friendly greeting with a comma.","I wrote an opening line.","I described two or three events with a detail and a feeling.","I used the past tense correctly (rode, slid, saw).","I used a friendly tone with contractions and a question for my friend.","I wrote a closing with a comma and my name.","My email is 80–100 words, and I checked spelling and capital letters."],"rubric_id":"RW-RUBRIC-5T","min_words":80,"max_words":130,"organizer":"Email Planner (header – greeting + opening – body 1 – body 2 – question – closing + name + P.S.)","items":[{"q":"Write an email (80–100 words) to a friend about a trip to a desert camp. Use the photo cards. Include a subject, a greeting, an opening, two or three events with details and feelings, a question for your friend, a closing and your name.","answer":"To: Layla · From: Noura · Subject: You won't believe my desert weekend! Hi Layla, How are you? I just got back from a weekend at a desert camp with my family, and I have so much to tell you! On Saturday morning, I rode a camel for the first time. It was so tall that I held on tight! In the afternoon, Faris and I slid down a huge dune on a sandboard. We laughed all the way down. At night, we sat around the fire and drank hot milk while my dad told stories. Have you ever been to a desert camp? I think you'd love it! Write back soon, Noura. P.S. I took a photo of the sunset for you!","_w":{"checklist":["My email has To, From and a clear subject.","I wrote a friendly greeting with a comma.","I wrote an opening line.","I described two or three events with a detail and a feeling.","I used the past tense correctly (rode, slid, saw).","I used a friendly tone with contractions and a question for my friend.","I wrote a closing with a comma and my name.","My email is 80–100 words, and I checked spelling and capital letters."],"min":80,"max":130}}]}],"game":{"name":"Postcard Relay","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Mailbox relay: the child chooses one strip for each part of the email in order; a friendly-tone meter fills when contractions and questions are used. A complete, correct email drops into the mailbox with a 'ding!'.","Each team gets a pile of mixed email strips.","Runner 1 chooses a subject and a greeting; Runner 2 chooses an opening and an event; Runner 3 adds a detail and a question; Runner 4 adds the closing and the name.","Each runner checks the commas before passing the email on.","The team reads its email aloud and 'posts' it.","Correct order = 3 points; friendly tone = 2 points; all commas correct = 2 points."],"data":[]},"exit_quiz":[{"q":"How long should your desert-trip email be?","answer":"80–100 words","explanation":"Length.","explanation_ar":"80–100 كلمة.","options":["10 words","80–100 words","500 words","one page of a book"],"dok":1,"skill":"length"},{"q":"*The camel **swayed** as it walked.* *Swayed* means ___.","answer":"moved slowly from side to side","explanation":"Sway.","explanation_ar":"تمايل.","options":["ran very fast","stopped","moved slowly from side to side","sat down"],"dok":1,"skill":"vocabulary in context"},{"q":"Which part of the email comes right after the greeting?","answer":"the opening line","explanation":"Order.","explanation_ar":"الجملة الافتتاحية.","options":["the P.S.","the closing","the opening line","the subject"],"dok":1,"skill":"email format"},{"q":"What should each event in the body include?","answer":"what happened, a detail and a feeling","explanation":"Details.","explanation_ar":"ما حدث + تفصيل + شعور.","options":["only the date","what happened, a detail and a feeling","only the names","a list of words"],"dok":1,"skill":"details"},{"q":"Which sentence about the falcon show is correct?","answer":"We saw a falcon land on the trainer's glove.","explanation":"saw + land.","explanation_ar":"صحيحة.","options":["We saw a falcon land on the trainer's glove.","We seen a falcon land on the trainer's glove.","We see a falcon landed on the glove yesterday.","We saw a falcon lands on the trainer's glove."],"dok":2,"skill":"grammar"},{"q":"Which sentence for a desert-trip email has a FRIENDLY tone?","answer":"I think you'd love it!","explanation":"Friendly.","explanation_ar":"ودية.","options":["Please be informed that the trip was good.","I am writing to inform you about my weekend.","Kindly reply at your earliest convenience.","I think you'd love it!"],"dok":2,"skill":"tone"},{"q":"Which closing and name are written correctly?","answer":"Write back soon, (new line) Noura","explanation":"Comma + name on a new line.","explanation_ar":"صحيحة.","options":["Write back soon Noura","Write back soon, (new line) Noura","write back soon, noura","Write back soon. Noura,"],"dok":2,"skill":"email format"},{"q":"Why should you choose only two or three events?","answer":"so your email stays short and each event has details","explanation":"Focus.","explanation_ar":"ليبقى البريد قصيرًا ومفصلًا.","options":["because the other events were boring","because emails can't have more than three sentences","so you don't need a greeting","so your email stays short and each event has details"],"dok":2,"skill":"planning"},{"q":"Which P.S. connects BEST to Layla's life?","answer":"P.S. Your cat Qamar would love chasing the jerboas!","explanation":"Personal.","explanation_ar":"يرتبط بحياة ليلى.","options":["P.S. Your cat Qamar would love chasing the jerboas!","P.S. The end.","P.S. Sand is yellow.","P.S. This is my email."],"dok":3,"skill":"tone"},{"q":"Your friend writes back: *I've never been to a desert camp. What should I bring?* What is the BEST reply?","answer":"Bring a warm jacket for the cold nights and shake your boots in the morning!","explanation":"Use what you learned.","explanation_ar":"رد مفيد.","options":["Bring a warm jacket for the cold nights and shake your boots in the morning!","I don't know.","Bring your school bag.","Nothing at all."],"dok":3,"skill":"replying"}],"images":[{"id":"IMG-RW-L04-U5-LS5-V01","prompt":"Picture for the word 'sway': a child on a camel moving side to side"},{"id":"IMG-RW-L04-U5-LS5-V02","prompt":"Picture for the word 'sandboard': a child sliding down a dune on a board"},{"id":"IMG-RW-L04-U5-LS5-V03","prompt":"Picture for the word 'slide': a child sliding down sand"},{"id":"IMG-RW-L04-U5-LS5-V04","prompt":"Picture for the word 'trainer': a falcon trainer with a glove"},{"id":"IMG-RW-L04-U5-LS5-V05","prompt":"Picture for the word 'glove': a thick leather glove"},{"id":"IMG-RW-L04-U5-LS5-V06","prompt":"Picture for the word 'sunset': an orange and pink desert sunset"},{"id":"IMG-RW-L04-U5-LS5-V07","prompt":"Picture for the word 'weekend': a calendar with Friday and Saturday circled"},{"id":"IMG-RW-L04-U5-LS5-01","prompt":"An email about a desert trip being sent and answered."},{"id":"IMG-RW-L04-U5-LS5-02","prompt":"Five desert trip photo cards."},{"id":"IMG-RW-L04-U5-LS5-03","prompt":"An email planner organizer."}],"audio":[{"id":"AUD-RW-L04-U5-LS5-V01","script":"sway. The camel swayed as it walked."},{"id":"AUD-RW-L04-U5-LS5-V02","script":"sandboard. We slid down the dune on a sandboard."},{"id":"AUD-RW-L04-U5-LS5-V03","script":"slide. Faris slid down the dune."},{"id":"AUD-RW-L04-U5-LS5-V04","script":"trainer. The falcon trainer wore a thick glove."},{"id":"AUD-RW-L04-U5-LS5-V05","script":"glove. The falcon landed on the glove."},{"id":"AUD-RW-L04-U5-LS5-V06","script":"sunset. The sunset was orange and pink."},{"id":"AUD-RW-L04-U5-LS5-V07","script":"weekend. We went camping for the weekend."},{"id":"AUD-RW-L04-U5-LS5-T1","script":"**Photo 1 – Arriving at the camp** · Friday afternoon · tents in a circle · the sun going down · the sky turns orange and pink **Photo 2 – A camel ride** · Saturday morning · the camel is very tall · it walks slowly and sways · hold on tight! **Photo 3 – Sandboarding** · a huge dune · climb up slowly, slide down fast · sand in your shoes · lots of laughing **Photo 4 – The falcon show** · a trainer with a thick glove · the falcon flies very fast · it lands on the glove · everyone claps **Photo 5 – Night at the camp** · a fire in the middle · hot milk or tea · stories from the grown-ups · thousands of stars"},{"id":"AUD-RW-L04-U5-LS5-VID","script":"Noura just came back from the desert. She can't wait to tell Layla! Choose two or three photos: the camel ride, sandboarding, the falcon show, the night fire… Plan with the Email Planner: subject, greeting, two short paragraphs, a question and a closing. On Saturday morning, I rode a camel for the first time. It was so tall that I held on tight! Check the commas, count the words and press send. Then wait for a reply!"}]}],"unit_test":[{"q":"The wind blew the sand into a tall hill. It made a new ___.","answer":"dune","explanation":"Dune.","explanation_ar":"كثيبًا.","options":["tent","burrow","glove","dune"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"At noon, the camels rested under a tree in the ___.","answer":"shade","explanation":"Shade.","explanation_ar":"الظل.","options":["heat","shade","sandstorm","sunset"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Shake your shoes in the morning – a ___ might be hiding inside!","answer":"scorpion","explanation":"Scorpion.","explanation_ar":"عقرب.","options":["falcon","scorpion","camel","cactus"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"The sky turned brown, and we couldn't see the road. It was a ___.","answer":"sandstorm","explanation":"Sandstorm.","explanation_ar":"عاصفة رملية.","options":["sunset","camp","sandstorm","peninsula"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"*Some desert plants **adapt** by growing very long roots.* *Adapt* means ___.","answer":"change to live well in a place","explanation":"Adapt.","explanation_ar":"تتكيّف.","options":["die quickly","move to the city","change to live well in a place","grow flowers every day"],"dok":1,"skill":"vocabulary in context","_part":"Part A – Vocabulary"},{"q":"The thermometer showed 48 °C. The ___ was very high.","answer":"temperature","explanation":"Temperature.","explanation_ar":"درجة الحرارة.","options":["temperature","environment","subject","view"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"The guide words on a dictionary page are *camp – cave*. Which word is on the page?","answer":"camel","explanation":"cas- comes after cam- and before cav-.","explanation_ar":"castle.","options":["cactus","castle","cabin","camel"],"dok":2,"skill":"guide words","_part":"Part A – Vocabulary"},{"q":"Which of these desert words comes FIRST in a dictionary?","answer":"dry","explanation":"de- before dr- and du-.","explanation_ar":"desert.","options":["dry","dune","desert","dust"],"dok":2,"skill":"ABC order","_part":"Part A – Vocabulary"},{"q":"Which greeting for Layla's email to her cousin Reem is correct?","answer":"Hi Reem,","explanation":"Capital + comma.","explanation_ar":"صحيحة.","options":["Hi Reem","Hi Reem,","hi reem,","Hi, reem."],"dok":1,"skill":"email format","_part":"Part D – Writing skills"},{"q":"Which subject line is BEST for Layla's email about the sandstorm?","answer":"Caught in a sandstorm!","explanation":"Clear + interesting.","explanation_ar":"الأفضل.","options":["Hi","Caught in a sandstorm!","Message","Read now!!!"],"dok":2,"skill":"email format","_part":"Part D – Writing skills"},{"q":"Which sentence for Layla's email has a FRIENDLY tone?","answer":"You won't believe what happened on our trip!","explanation":"Friendly.","explanation_ar":"ودية.","options":["I am writing to inform you about our journey.","Please be advised that a sandstorm occurred.","You won't believe what happened on our trip!","Kindly reply to this message."],"dok":2,"skill":"tone","_part":"Part D – Writing skills"},{"q":"Which contraction in Layla's email is written correctly?","answer":"We couldn't see the road.","explanation":"Apostrophe.","explanation_ar":"صحيحة.","options":["We couldn't see the road.","We couldnt see the road.","We could'nt see the road.","We could,nt see the road."],"dok":2,"skill":"contractions","_part":"Part D – Writing skills"},{"q":"Which question would be BEST near the end of Layla's email?","answer":"Have you ever been in a sandstorm?","explanation":"Question for the friend.","explanation_ar":"السؤال الأفضل.","options":["Have you ever been in a sandstorm?","Why is the car blue?","What is the date today?","Do you know my name?"],"dok":2,"skill":"tone","_part":"Part D – Writing skills"},{"q":"Layla's email ends like this. Which ending is written correctly?","answer":"Write back soon, (new line) Layla","explanation":"Comma + name.","explanation_ar":"صحيحة.","options":["Write back soon Layla","write back soon, layla","Write back soon. (new line) Layla,","Write back soon, (new line) Layla"],"dok":1,"skill":"email format","_part":"Part D – Writing skills"}],"unit_writing":{"task":"Imagine you were with Layla's family in the sandstorm. Write an email (80–100 words) to a friend about the trip. Include a subject, a greeting, an opening, two or three events with details and feelings, a question for your friend, a closing and your name.","model":"To: Sami · From: Hamza · Subject: Caught in a sandstorm! Hi Sami, How are you? You won't believe what happened on our way to the desert camp! Suddenly, the sky turned brown, and sand hit the windows like rain. We couldn't see anything, so Uncle stopped the car. I was a little scared, but he told us funny stories while we waited. After an hour, the sky was blue again, and sand covered everything, even our shoes! Have you ever been in a sandstorm? I hope you never are! See you soon, Hamza. P.S. I still have sand in my ears!","marks":20}});
